INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9340, 'plPL', 'Wielka Szczelina', 'Niebezpiecznie blisko nam do okrążenia przez siły Przymierza. Wobec napływu pielgrzymów sin\'dorei z Azeroth musimy wytyczyć szlak bezpieczny przed wścibskimi oczami wrogów.$B$BPrzemyślałem sprawę i znalazłem rozwiązanie. Wytyczymy tajną ścieżkę przez Wielką Szczelinę.$B$BTak, wiem, że roi się tam od brutalnych skalnych oprawców, ale to tylko zwierzęta, a zwierzęta można nauczyć strachu. Idź tam i zabij ich całkiem sporo. Nauczą się bać.', 'Kapitan tropicieli Venn\'ren w Sokolej Strażnicy chce, żebyś $gzabił:zabiła; 8 kamiennokosych piskląt i 3 kamiennokose samce alfa w Wielkiej Szczelinie, na wschód od Sokolej Strażnicy.', '', 'Wróć do kapitana tropicieli Venn\'rena w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9342, 'plPL', 'Grasujące kruszyciele skorupy', 'Jakby mało było gan\'argów, które opanowały kopalnie, to teraz z drugiej strony pełzną na nas olbrzymie czerwie!$B$BGarnizon Thrallmaru jest przygwożdżony obroną przed Legionem i opieką nad rannymi, więc z kłopotami muszę sobie radzić sam, razem z górnikami.$B$B<Brygadzista wskazuje śpiących peonów.>$B$BA sam widzisz, jaki z nich pożytek...$B$BChętnie oddam ci ich zapłatę, jeśli przetrzebisz trochę tych czerwi.', 'Brygadzista Razelcraz z kopalni przy Thrallmarze chce, żebyś $gzabił:zabiła; 15 grasujących kruszycieli skorupy. Czerwie mają zwyczaj atakować znienacka ze swoich podziemnych tuneli.', '', 'Wróć do brygadzisty Razelcraza w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9344, 'plPL', 'Pospieszny wymarsz', 'Witaj, $N. Rubież to niebezpieczne miejsce, o czym wielu członków naszej wyprawy szybko się przekonało. Obawiam się, że młody Grelag mógł przekonać się o tym na własnej skórze.$B$BGrelag to obiecujący uczeń, ale brak mu cierpliwości! Z zapałem zgłębia historię swojego ludu, lecz czasem zapomina o zagrożeniach teraźniejszości.$B$BWyruszył do Posterunku Łamigrzbietów, nie wiedząc nic o Legionie ani o spaczonych orkach, którzy tam grasują. Boję się, że coś mu się stało.', 'Wieszczka Regulkut chce, żebyś $godnalazł:odnalazła; jej ucznia Grelaga.', '', '', '', '', '', '', 0),
(9345, 'plPL', 'Przygotowanie maści', 'Gdy tylko ujrzałem Zeth\'Gor, dostrzegł mnie patrol Legionu. Rzuciłem się do ucieczki, licząc, że schowam się w jednej z wież w oddali, ale jeden z ich ogarów spaczenia dopadł mnie i omal nie przeciął mi ścięgien!$B$BUdało mi się uciec, ale noga jest w fatalnym stanie. Kamienny strażnik Ambelan znalazł mnie i przyprowadził tutaj.$BTeraz muszę jakoś zająć się tą nogą. W Dolinie Kości na północy i wokół niej rośnie kolcolist. Maść z niego uśmierzy ból na tyle, żebym mógł ruszyć w drogę.', 'Zbierz 12 roślin kolcolistu Piekielnego Ognia na maść i wróć do Grelaga w Posterunku Łamigrzbietów.', '', 'Wróć do Grelaga w Posterunku Łamigrzbietów na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9346, 'plPL', 'Gdy piekielne dziki zaczną latać', 'Widział kto kiedy latającego piekielnego dzika? Nawet skrzydeł nie potrzebują!$B$B<Komendant straży Krunk wybucha śmiechem.>$B$BWalka z obozami Legionu na północy wyczerpała nasze zapasy, w tym amunicję do katapult. To świetna okazja, żeby spróbować czegoś nowego.$B$BZamiast głazów chcę podpalać truchła wygłodzonych piekielnych dzików, które widziałem przy wschodnich ruinach, i ostrzeliwać nimi obozy Legionu.$B$BZgłosisz się na ochotnika czy mam ci rozkazać?', 'Komendant straży Krunk w Thrallmarze chce, żebyś $gprzyniósł:przyniosła; mu 10 tłustych tusz piekielnego dzika z wygłodzonych piekielnych dzików.', '', 'Wróć do komendanta straży Krunka w Kanionie Kamiennego Muru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9347, 'plPL', 'Wędrowcy Pustki na wolności', 'Przyglądając się esencji, dostrzegasz gwałtowne wiry energii zamknięte w naczyniu z nieznanego materiału. Gdy się nad nią zastanawiasz, czujesz, jak zaczyna szarpać twój umysł i zachęca, byś $gpodszedł:podeszła; bliżej i $gzajrzał:zajrzała; głębiej.$B$BCzując, że twoja wola zaczyna słabnąć, natychmiast odwracasz wzrok. Jej obecność pozostaje jednak na skraju twojej świadomości, gdy zastanawiasz się, co z nią zrobić.', 'Zanieś pulsującą esencję wędrowca Pustki Mahuramowi Mocnemu Kopytu w Thrallmarze.', '', '', '', '', '', '', 0),
(9348, 'plPL', 'Obława na pustoszycieli', 'Rubież roi się od fascynujących stworzeń. Fascynujących – i niezwykle niebezpiecznych.$B$BW okolicy pełno jest drapieżników, co dziwi w tak jałowej krainie, ale bliższe przyjrzenie się ujawnia pewną hierarchię.$B$BSkalni oprawcy chyba udomowili innego drapieżnika, pustoszyciela, i hodują go jako towarzysza łowów i zwierzę stróżujące. Muszę się dowiedzieć, jak szkolą te pustoszyciele. Musimy zniszczyć i zbadać ich wylęgarnię na południowym zachodzie, w pobliżu Puszczy Terokkar.', 'Zabij 10 pojmanych piskląt pustoszyciela i zdobądź 12 jaj pustoszyciela dla Mahurama Mocnego Kopyta w Thrallmarze.', '', 'Wróć do Mahurama Mocnego Kopyta na Pustkowiach Sha\'naari na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9349, 'plPL', 'Zbiórka jaj pustoszyciela', 'Umieram z głodu!$B$BIronia, nie sądzisz? Głodujący kucharz?$B$B<Legassi śmieje się bez przekonania i klepie złożony kawałek pergaminu w kieszeni.>$B$BWedług tej mapy turystycznej, którą się kierowaliśmy – zanim tak niegrzecznie nas zestrzelono – na południowym zachodzie, w pobliżu Puszczy Terokkar, jest miejsce zwane Szlakiem Brzytwocierni. Podobno aż roi się tam od pysznych jaj pustoszycieli!$B$BUrządziłbym niezłą ucztę, gdyby tylko ktoś był na tyle odważny, żeby tam pójść i mi ich przynieść!', 'Zdobądź 12 jaj pustoszyciela dla Legassiego przy Wraku Sterowca na Półwyspie Piekielnego Ognia.', '', 'Wróć do Legassiego przy Wraku Sterowca na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9350, 'plPL', 'Praca peona nigdy się nie kończy', 'Nieustanne ataki Legionu mocno nadwyrężają naszą obronę. Jeśli padnie palisada, padnie i Thrallmar. Wyznaczyłem peonów do wzmacniania i naprawy murów, ale kończą nam się materiały.$B$BGrelag, jeden z uczniów wieszczki, zna dobrze dawne obyczaje i zaproponował powrót do starodawnej praktyki. Dawno temu polowania na rozłupokopyty dostarczały nam mięsa, skór i kości. Wznowienie łowów na rozłupokopyty na południowym wschodzie dałoby nam to, czego potrzeba, i oddałoby cześć przodkom.', 'Zdobądź 8 skór rozłupokopyta i 8 zestawów kości rozłupokopyta z szalejących rozłupokopytów. Gdy zbierzesz wszystkie materiały, wróć do komendanta straży Krunka w Thrallmarze.', '', 'Wróć do komendanta straży Krunka w Kanionie Kamiennego Muru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9351, 'plPL', 'Wędrowcy Pustki na wolności', 'Nawet jeśli zdołam naprawić szkielet sterowca, będę musiał znaleźć coś innego do zasilania silnika. Skończyło mi się paliwo, a w okolicy nie ma gdzie zatankować!$B$BNa południe od nas leży kraina spękanej ziemi zwana Polami Spaczeń. Pełno tam zbłąkanych i nieokiełznanych wędrowców Pustki, ale ja wolę myśleć o nich jak o chodzących bateriach.$B$BJeśli przyniesiesz mi dość ich esencji, przerobię silnik sterowca, żeby na niej działał. Stawiam pięć sztuk złota, że będzie nawet mniej palił!', 'Przynieś 10 skondensowanych esencji wędrowca Pustki „Wrzeszczącemu” Screedowi Luckheedowi przy Wraku Sterowca.', '', 'Wróć do „Wrzeszczącego” Screeda Luckheeda przy Wraku Sterowca na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9354, 'plPL', 'W poszukiwaniu nowych materiałów', '<Krasnolud z wyczekiwaniem odrywa wzrok od pracy.>$B$BJeśli chcesz coś zamówić, ustaw się w kolejce, $N. Mam pełne ręce roboty z utrzymaniem sprzętu Synów i przygotowaniami na dzień, w którym znów ruszymy na wroga.$B$BZapasy metalu bardzo nam się skurczyły, odkąd kopalnie opanowały świdraki skorupy. Eksperymentuję z naturalnymi materiałami z szalejących rozłupokopytów, które pasą się na północny wschód od Warowni, i choć żelaza nie zastąpią, uczę się sobie radzić.', 'Zdobądź 8 skór rozłupokopyta i 8 ścięgien rozłupokopyta z szalejących rozłupokopytów. Gdy zbierzesz materiały, zanieś je Humphry\'emu w Warowni Honoru.', '', 'Wróć do Humphry\'ego na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9355, 'plPL', 'Zadanie dla bystrego człowieka', 'Bądź pozdrowiony, $N. Teraz, gdy wreszcie przybywają posiłki, możemy odzyskać choć namiastkę normalnego życia.$B$BJednym z pierwszych celów jest przywrócenie ruchu ludzi i towarów na drodze na południowy zachód, ale najpierw trzeba ją odbić z rąk kruszycieli skorupy, które opanowały okolicę.$B$BJeśli zechcesz pomóc nam uporać się z tą plagą, zyskasz wdzięczność Synów. Uważnie wypatruj poruszonej ziemi, którą zostawiają za sobą.', 'Zabij 15 grasujących kruszycieli skorupy i wróć do brygadzisty Biggumsa w Warowni Honoru.', '', 'Wróć do brygadzisty Biggumsa w Kopalni Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9356, 'plPL', 'Jak po maśle', 'Screed lubi mawiać, że lata „jak po maśle”. Moim zdaniem to raczej ręce ma z masła – wszystko mu się z nich wyślizguje!$B$BSpójrz tylko na tamten wrak. On to nazywa „twardym” lądowaniem.$B$BNo dobrze, ostrzelano nas, ale byłbym dla niego bardziej wyrozumiały, gdyby tak często nie przechwalał się swoim pilotażem!$B$BChyba przygotuję mu porcję skrzydełek, żeby dotarło do niego, o co mi chodzi. Na wschodzie, w Dolinie Kości, znajdziesz sępy kościołupy. Mają tłuste, soczyste skrzydła, w sam raz do moich celów.', 'Przynieś 12 tłustych skrzydeł sępa Legassiemu przy Wraku Sterowca.', '', 'Wróć do Legassiego przy Wraku Sterowca na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9361, 'plPL', 'Piekielny dzik, drugie białe mięso', 'Te jaja są wyborne, ale co powiesz na to, żebyśmy podkręcili to jeszcze o oczko?$B$BPorcja boczku idealnie dopełniłaby posiłek, a ja wiem, skąd go wziąć.$B$BTo miejsce aż roi się od piekielnych dzików. Oczywiście nie ma tu nikogo, kto zbadałby i skruszył mięso, ale mamy szczęście!$B$B<Legassi grzebie w plecaku i wyciąga flaszkę.>$B$BTo nie było robione z myślą o wieprzowinie, ale w gotowaniu improwizacja liczy się tak samo jak wszystko inne!', 'Legassi przy Wraku Sterowca chce, żebyś $gzebrał:zebrała; 8 porcji oczyszczonego mięsa piekielnego dzika. Aby oczyścić mięso, użyj mieszanki oczyszczającej na skażonym mięsie piekielnego dzika zdobytym z piekielnych dzików.', '', 'Wróć do Legassiego przy Wraku Sterowca na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9366, 'plPL', 'Potrzebna spaczona krew', 'Na północny wschód stąd leżą Sadzawki Aggonara. Niegdyś były miejscem świętym dla draenei, ale ich wody zostały skażone, gdy wlała się do nich krew demona Aggonara.$B$BTa krew, choć stara i rozcieńczona, wciąż kryje ogromną moc. Po okolicy krążą teraz straszydła grozy, wzmocnione czystą demoniczną energią pierwotnej krwi. Zabij je i zdobądź jak najwięcej spaczonej krwi. Sowicie ci to wynagrodzę.', 'Ryathen Posępny w Sokolej Strażnicy na Półwyspie Piekielnego Ognia chce, żebyś $gprzyniósł:przyniosła; mu 6 próbek spaczonej krwi ze straszydeł grozy zamieszkujących Sadzawki Aggonara.', '', 'Wróć do Ryathena Posępnego w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9370, 'plPL', 'Oczyszczenie trzeba powstrzymać', 'Nasi zwiadowcy pojmali draenejskiego paladyna przy Sadzawkach Aggonara. Miał wziąć udział w rytuale, który oczyściłby sadzawki. Musimy nie dopuścić do sukcesu draenei, bo stracimy źródło spaczonej krwi!$B$BMiał przy sobie ten klejnot sygnałowy – chciał nim oznaczyć miejsce, w którym kapłan, czy też „anachoreta”, jak sami siebie nazywają, mógłby bezpiecznie odprawić swoje rytuały. Umieść klejnot przy Ołtarzu Aggonara i bądź $ggotów:gotowa; urządzić zasadzkę na każdego nadchodzącego draenei.$B$BRadzę zabrać ze sobą przyjaciela czy dwóch.', 'Umieść klejnot sygnałowy przy Ołtarzu Aggonara w Sadzawkach Aggonara i pokonaj wszystkich draenejskich anachoretów, którzy odpowiedzą na twoje wezwanie. Po wykonaniu zadania wróć z klejnotem sygnałowym do Ryathena Posępnego w Sokolej Strażnicy.', '', 'Wróć do Ryathena Posępnego w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9372, 'plPL', 'Demoniczne skażenie', 'Witaj w Posterunku Cenariona, $N. Rzadko miewamy tu gości, więc cieszę się z odwiedzin. Moja praca ze stworzeniami tej wyludnionej krainy wymaga wypraw w wiele odległych miejsc.$B$BEkspedycja Cenariońska wysłała mnie, bym zbadała jedne z najgroźniejszych zwierząt Rubieży, i dokonałam zdumiewającego odkrycia. Choć wiele tutejszych stworzeń przeszło już radykalne zmiany, wciąż mutują. Zbieram próbki krwi, by udokumentować te zmiany, i każda pomoc będzie mile widziana.', 'Thiah Rudogrzywa z Posterunku Cenariona na Półwyspie Piekielnego Ognia poprosiła cię o zebranie 6 próbek krwi piekielnego dzika z potężnych piekielnych dzików.', '', 'Wróć do Thiah Rudogrzywej w Posterunku Cenariona na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9373, 'plPL', 'Zaginione pismo', 'Po obejrzeniu sfatygowanego skórzanego futerału staje się jasne, że uszkodził go żrący płyn z przewodu pokarmowego czerwia. Skóra wygląda na niegdyś misternie tłoczoną, ale szczegółów zdobień nie da się już rozpoznać.$B$BJedynym rozpoznawalnym elementem futerału jest wytarty znak Kręgu Cenariona. Nie wiedząc nic o zawartości futerału, uznajesz, że najlepiej będzie dostarczyć go komuś z Kręgu.', 'Zanieś nadżarty skórzany futerał Thiah Rudogrzywej, która obozuje w pobliżu Ruin Sha\'naar w zachodniej części Półwyspu Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9374, 'plPL', 'Dziennik Areliona', 'Mój mąż, Arelion, był zafascynowany Sadzawkami Aggonara, odkąd przybyliśmy do Rubieży. Spędzał mnóstwo czasu na badaniu... szlamów, wyobraź sobie!$B$BKilka dni temu zaginął tam. Mówią, że nie żyje i że nic nie mogę na to poradzić.$B$BMogę za to zadbać, by jego badania nie umarły razem z nim. Idź na północny wschód, do sadzawek, i poszukaj jego dziennika. Zawsze nosił go w brązowym plecaku.', 'Magistrix Carinda w Sokolej Strażnicy na Półwyspie Piekielnego Ognia chce, żebyś $gposzedł:poszła; do Sadzawek Aggonara i $godzyskał:odzyskała; dziennik Areliona.', '', 'Wróć do magistrix Carindy w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9375, 'plPL', 'Droga do Sokolej Strażnicy', '<Na twarzy poturbowanej krwawej elfki maluje się ulga na twój widok.>$B$BProszę, $N, wydostań mnie z tej klatki! Głupio zrobiłam, wyruszając z Thrallmaru przed główną grupą, choć Martik Tor\'seldori ostrzegał.$B$BNapadły mnie straszne stwory – to musiały być pustoszyciele, o których mówił. Zdołałam je odpędzić, ale to był dopiero początek moich kłopotów.$B$BGdy opatrywałam rany, znaleźli mnie ci ptasi ludzie, zawlekli do tej jaskini i zamknęli w klatce! Muszę dostać się do Sokolej Strażnicy!', 'Chroń ranną pielgrzymkę krwawych elfów w drodze do Sokolej Strażnicy, a potem porozmawiaj z Talerisem Świtowidzem.', 'Odeskortuj ranną pielgrzymkę krwawych elfów do Sokolej Strażnicy', 'Porozmawiaj z Talerisem Świtowidzem w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9376, 'plPL', 'Niedola pielgrzymki', 'Ta ranna pielgrzymka krzyczy chyba coś o jakimś plecaku.$B$BKiedy ją $gspotkałeś:spotkałaś;, $gwidziałeś:widziałaś; w pobliżu jakiś plecak? Hmm...$B$BMusiała go zostawić, uciekając przed napastnikami. Kolcokłe pustoszyciele z parowu na południu słyną z atakowania samotnych podróżnych.$B$BJeśli się nie uspokoi, nie zdołam opatrzyć jej ran. Ten upór może ją kosztować życie.$B$BIdź do Parowu Pyłopiórych i poszukaj jej obozowiska. Założę się, że tam go zostawiła.', 'Ranna pielgrzymka krwawych elfów została zaatakowana przez kolcokłe pustoszyciele, gdy obozowała w Parowie Pyłopiórych. Odnajdź jej obóz i poszukaj tam zaginionego plecaka.', '', 'Wróć do Talerisa Świtowidza w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9377, 'plPL', 'Głód mocy', 'Sokola Strażnica służy za przystanek dla pielgrzymów w ich długiej wędrówce przez Rubież. Choć jesteśmy jednym z pierwszych przystanków na trasie, wielu pielgrzymów dociera do nas wyczerpanych i dręczonych przez swoje nałogi.$B$BW takim świecie wielu musi na nowo nauczyć się panować nad magicznym nałogiem. Jedzenie i picie pomagają, $N, ale najbardziej potrzebują energii magicznej. Szczątki wędrowców Pustki z Rubieży to silne źródło energii, ale jest ich coraz mniej i można je znaleźć tylko na Polach Spaczeń na południowym zachodzie.', 'Zdobądź silną esencję wędrowca Pustki z mściwych wędrowców Pustki i wróć do Talerisa Świtowidza w Sokolej Strażnicy.', '', 'Wróć do Talerisa Świtowidza w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9379, 'plPL', 'Wzmocnienie łowcy spaczenia', 'Witaj, $N. Przywitaj się też z Jir\'see. Nie bój się, nie ugryzie, chyba że mu każę.$B$B<Angela grucha czule do łowcy spaczenia.>$B$BJest taki malutki w porównaniu z ogarami wypaczenia, które żyją na Rubieży. Ale zaraz to naprawimy, o tak, naprawimy, prawda, Jir\'see?$B$BChyba wymyśliłam, jak to zrobić. Potrzebuję mnóstwo krwi ogarów wypaczenia i tu wkraczasz ty. Kiedy będziesz na nie polować na południowym wschodzie, ja przygotuję się do ekspery... ee, zabiegu.', 'Zbierz 6 porcji krwi ogara wypaczenia i zanieś je Angeli „Pazur” Kestrel w Thrallmarze.', '', 'Wróć do Angeli „Pazur” Kestrel na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9380, 'plPL', 'Cała sfora ogarów', 'Słowo daję, jeśli dostanę jeszcze jeden list z Żelaznej Kuźni...$B$B$GPróbowałeś:Próbowałaś; kiedyś coś wytłumaczyć komuś, kto po prostu nie chce słuchać, $N? Wysłałem chłopakom w Żelaznej Kuźni ogara wypaczenia, o którego prosili, a oni mieli czelność odpisać, że chcą całą „sforę” tych stworów! Sforę!$B$BPróbowałem im wytłumaczyć, że ogary wypaczenia to samotniki, ale nie chcieli słuchać. Dałem sobie spokój z prostowaniem im w głowach. Złap 6 najlepszych na terenie na wschód od warowni i przynieś je tutaj, dobra?', 'Zbierz 6 nieuszkodzonych zwłok ogara wypaczenia i zanieś je poszukiwaczowi Murantusowi w Warowni Honoru.', '', 'Wróć do poszukiwacza Murantusa na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9381, 'plPL', 'Niechybne strzały', 'Przez napływ pielgrzymów i napór sił Przymierza w Sokolej Strażnicy zrobiło się ostatnio bardzo tłoczno. W wolnym czasie zwykle pomagam szykować strzały dla tropicieli, ale od dawna nie miałam okazji nazbierać piór na lotki.$B$BMogę ci zapłacić, jeśli zechcesz zebrać pióra ogonowe ścierwników kościołupów. Dawniej widywałam je, jak krążyły nad kośćmi wielkich bestii na północ od Sokolej Strażnicy.', 'Zbierz 8 piór ogonowych kościołupa ze ścierwników kościołupów i zanieś je sokolniczce Drennie Rzecznemu Wiatrowi w Sokolej Strażnicy.', '', 'Wróć do sokolniczki Drenny Rzecznego Wiatru w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9382, 'plPL', 'Los rozłupokopytów', 'Witaj, $N.$B$BJestem pewien, że podróże po Rubieży pokazały ci co nieco ze skażenia tego świata. Jest tak wszechobecne, że odmieniło nawet żyjące tu stworzenia – przynajmniej te, które przetrwały.$B$BRozłupokopyty na południu i zachodzie były niegdyś łagodnymi zwierzętami pasącymi się w spokoju, ale skażenie rozpaliło w nich nieugaszoną wściekłość. Wyzwolenie od udręki przynosi im dopiero śmierć, choć smuci nas przelewanie ich krwi. Pomożesz mi zakończyć cierpienie szczeciniastych rozłupokopytów?', 'Zabij 15 szczeciniastych rozłupokopytów i wróć do Amaana Mądrego w Świątyni Telhamat.', '', 'Wróć do Amaana Mądrego na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9383, 'plPL', 'Ambitny plan', 'Krwawe elfy to wcielenie nieodpowiedzialnego używania magii, $N. Nie panują nad magiczną energią. Przeciwnie, są jej niewolnikami i nie ścierpią niczego, co stanęłoby między nimi a ich nałogiem. Pochłaniają energię wędrowców Pustki z Rubieży, by zasilać swoją demoniczną magię.$B$BPrzygotowałam kryształ naładowany zaklęciem, które pozwoli nam zneutralizować wędrowca Pustki i zerwać jego więź z tym światem, gdy zostanie zniszczony. Wędrowców Pustki widywałam głównie na Polach Spaczeń na południowy wschód od Cytadeli Piekielnego Ognia.', 'Użyj uświęconego kryształu na rannym nieokiełznanym wędrowcu Pustki i wróć do Elsaany w Świątyni Telhamat.', '', 'Wróć do Elsaany w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9384, 'plPL', '<NYI>Ujarzmienie Światła', 'Nadszedł czas, by zniszczyć tego demona. Zalecam przy tym ostrożność, $N, bo wiele jeszcze nie wiesz o wędrowcach Pustki z Rubieży.$B$BZanieś to naczynie Rumatu, który dopilnuje jego zniszczenia. Uważnie obserwuj cały proces i zdaj mi relację, gdy dobiegnie końca.', 'Zanieś lśniący uświęcony kryształ Rumatu w Świątyni Sha\'naar, który przywoła Światło, by porazić uwięzionego w nim demona.', '', 'Wróć do Elsaany na Półwyspie Piekielnego Ognia.', 'Pomóż zniszczyć wędrowca Pustki', '', '', '', 0),
(9385, 'plPL', 'Szalejące pustoszyciele', 'No więc Warownia Honoru wysyła nas, żebyśmy się rozprawili z arakkoa, a my rozbijamy tu obóz i myślimy sobie: hej, czy to nie świetne miejsce? Nie mieliśmy pojęcia, jak blisko są kolcokłe pustoszyciele.$B$BTo nieustępliwe drapieżniki i przez nie nie da się tu nic zrobić. Dostaniesz trochę grosza, jeśli się z nimi za nas rozprawisz. Dasz radę?', 'Zabij 10 kolcokłych pustoszycieli i wróć do Gremniego Długobrodego na Półwyspie Piekielnego Ognia.', '', 'Wróć do Gremniego Długobrodego na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9387, 'plPL', 'Źródło skażenia', 'Nieskażeni draenei, tacy jak ten nieszczęśnik, to cnotliwi czempioni Światła. Jakie skażenie sprawiło, że ich wielka rasa zwyrodniała w Złamanych i Zagubionych?$B$BSłyszałem teorię, że mutację wywołało wystawienie na energię spaczenia. Chciałbym ją sprawdzić.$B$BNa północny zachód stąd leżą Ruiny Sha\'naar. Znajdziesz tam nędznych Złamanych, którymi dowodzą nadzorcy Illidari. Przynieś mi demoniczne esencje z nadzorców, żebym mógł wypróbować je na tym draenei.', 'Udaj się do Ruin Sha\'naar na Półwyspie Piekielnego Ognia i zdobądź 5 demonicznych esencji z nadzorców Illidari. Po wykonaniu zadania wróć do aptekarza Azethena w Sokolej Strażnicy.', '', 'Wróć do aptekarza Azethena w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9390, 'plPL', 'W poszukiwaniu Sedaia', 'Wysłuchaj mojej niedoli, $N. Mój brat Sedai wyruszył dawno temu, by nawiązać kontakt z orkami z Posterunku Mag\'harów. Wieczny idealista – uważał, że nadszedł czas, by odłożyć na bok dzielące nas różnice i wynegocjować z nimi pokój.$B$BNie ma go od wielu dni i obawiam się najgorszego.$B$BUspokoisz moje serce i go poszukasz? Sedai musi być gdzieś w pobliżu, na wschodzie.', 'Anachoreta Obadei chce, żebyś $gposzukał:poszukała; jego brata Sedaia w pobliżu, na wschodzie Półwyspu Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9391, 'plPL', 'Oznaczenie szlaku', 'Skalnych oprawców jest już mniej, więc zostało tylko wskazać bezpieczną ścieżkę naszym pielgrzymom. Wróć z tą pochodnią do Wielkiej Szczeliny i odszukaj trzy latarnie, które znaczą szlak od wschodu.$B$BZapal wszystkie trzy i wróć do mnie. Uważaj: gdy zapalisz latarnię, zwabi ona wszystkich skalnych oprawców z okolicy.', 'Kapitan tropicieli Venn\'ren w Sokolej Strażnicy chce, żebyś $gposzedł:poszła; do Wielkiej Szczeliny na Półwyspie Piekielnego Ognia i $gzapalił:zapaliła; Południową, Zachodnią i Centralną latarnię. Po wykonaniu zadania wróć do niego z zapaloną pochodnią.', '', 'Wróć do kapitana tropicieli Venn\'rena w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9396, 'plPL', 'Magia arakkoa', 'Rubież kryje wiele tajemnic, $N. To tylko kwestia czasu, zanim odkryjemy je wszystkie.$B$BArakkoa, pół ptaki, pół ludzie, posiadają pradawną wiedzę tajemną, która bardzo pomogłaby nam w zgłębianiu tego świata. Udaj się do Nory Haal\'esh na południe stąd. Zdobądź wszelkie magiczne zwoje, które mogą mieć przy sobie Haal\'eshi, i przynieś mi je.', 'Przynieś 4 zwoje Haal\'eshi arkaniście Calesthrisowi Gwieździe Świtu w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', 'Wróć do arkanisty Calesthrisa Gwiazdy Świtu w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9397, 'plPL', 'Ptaki z jednego gniazda', 'Arakkoa z Haal\'esh udomowili piękny gatunek ptaków zwanych kaliri.$B$BUdało mi się złapać młodego samca i wygląda na to, że dają się tresować. Samice są znacznie rzadsze, ale gdybym miała jedną, mogłabym spróbować je rozmnażać. Musi być jednak młoda... pisklę. Starszy dziki ptak nie przeżyłby w niewoli.$B$BWeź tę klatkę i udaj się na południe, do Nory Haal\'esh. Przeszukaj gniazda w poszukiwaniu jaj, z których zaraz coś się wykluje. Jeśli przyniesiesz mi pisklę samicy, sowicie cię wynagrodzę.', 'Udaj się do Nory Haal\'esh na Półwyspie Piekielnego Ognia i przeszukaj gniazda kaliri, by znaleźć pisklę samicy kaliri. Złap je do pustej klatki dla ptaków i zanieś sokolniczce Drennie Rzecznemu Wiatrowi w Sokolej Strażnicy.', '', 'Wróć do sokolniczki Drenny Rzecznego Wiatru w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9398, 'plPL', 'Zabójcze drapieżniki', 'Złamani, którzy żyją na Rubieży, zaznali niekończącej się przemocy. Nic dziwnego, że gdy tylko otworzył się Mroczny Portal, ruszyli do niego tłumnie w nadziei na ucieczkę z tej krainy.$B$BNiestety dla naszych zagubionych braci i sióstr idących z południa skalni oprawcy z Wielkiej Szczeliny widzą w nich łatwą zdobycz. Idź tam i przetrzeb skalnych oprawców, żeby nasi pobratymcy mieli jakąś szansę.', 'Zwiadowczyni Vanura w Świątyni Telhamat na Półwyspie Piekielnego Ognia chce, żebyś $gzabił:zabiła; 8 kamiennokosych piskląt i 4 kamiennokose samce alfa.', '', 'Wróć do zwiadowczyni Vanury w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9399, 'plPL', 'Okrutni nadzorcy', 'Pewnie myślisz, że większość Złamanych to źli ludzie, prawda? W rzeczywistości wielu z nich po prostu nie ma przewodnika.$B$BZanim poznałem Omenai, ja też byłem zagubiony.$B$BNasze umysły straszliwie ucierpiały od demonicznej magii orków. Łatwo nas zmylić i wykorzystać.$B$BDemony sprzymierzone z Illidanem codziennie napadają na Półwysep i porywają naszych w niewolę. Dzięki Omenai mamy teraz nadzieję. Udaj się do Ruin Sha\'naar na południowy zachód stąd i zabij nadzorców Illidari, by mój lud był wolny!', 'Zabij 4 nadzorców Illidari w Ruinach Sha\'naar i wróć do Ikana w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', 'Wróć do Ikana w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9400, 'plPL', 'Zabójca', '$N, niedawno wykryliśmy spisek mający na celu zabicie naszego wysłannika do Sokolej Strażnicy. Cytadela Piekielnego Ognia dowiedziała się dziś rano o naszym planie wysłania tam wyprawy i zastawiła zasadzkę.$B$BZwiadowcy donoszą mi, że zabójca znany jako Krun Łamigrzbiet czeka przy drodze na północ od Cytadeli. Idź tam i zabij tego zabójcę. Pokaż spaczonym orkom, że z nami nie ma żartów!', 'Nazgrel chce, żebyś $gudał:udała; się na drogę na północ od Cytadeli Piekielnego Ognia i $godszukał:odszukała; zabójcę imieniem Krun Łamigrzbiet.', 'Odnajdź Kruna Łamigrzbieta', 'Zbadaj zwłoki spaczonego orka na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9401, 'plPL', 'Dziwna broń', 'Wyciągasz kamienny topór z ciała, by lepiej mu się przyjrzeć. Wykonanie tej broni jest w jakiś sposób niezwykłe.$B$BWygląda na orkową robotę, choć materiały nie przypominają niczego, co dotąd $gwidziałeś:widziałaś;. Nazgrela może zainteresować ta broń.', 'Zanieś ciężki kamienny topór Nazgrelowi w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9405, 'plPL', 'Polecenie wodza', 'Jak wiesz, wódz poparł tę wyprawę całą swoją władzą z jednego powodu. To świat, z którego przybyliśmy. Tu są nasze korzenie.$B$BDla orków i dla krwawych elfów ta podróż znaczy co innego. Dla nich to poszukiwanie ziemi obiecanej. Dla nas to raczej powrót do domu.$B$BKtokolwiek zrobił ten topór, zna dawne obyczaje, i musimy się z nim skontaktować. To zbyt ważne, żeby polegać na zwykłych metodach tropienia. Pokaż broń wieszczce Regulkut – ona będzie wiedziała, co robić.', 'Zanieś ciężki kamienny topór wieszczce Regulkut w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9406, 'plPL', 'Mag\'harowie', 'Te wieści, które przynosisz zza Mrocznego Portalu... chcesz, żebyśmy uwierzyli, że syn Durotana włada teraz ziemiami po drugiej stronie... wolny od wszelkiego demonicznego skażenia? I że jego lud powrócił teraz na ten świat?$B$BDla twojego dobra mam nadzieję, że to nie jakiś żart, $N. Tego, co to znaczy dla mojego ludu... nie da się opisać. Muszę natychmiast posłać wieść do Nagrandu! Piekłorycz musi się o tym dowiedzieć.$B$BZanieś ten list swojemu przywódcy w Thrallmarze. Powiedz mu, że Mag\'harowie was witają!', 'Dostarcz list od Mag\'harów Nazgrelowi w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9408, 'plPL', 'Zapomniani bohaterowie', 'Choć boli mnie świadomość, że straciliśmy tylu żołnierzy, próbując przebić się przez portal, serce rośnie mi z dumy, że pierwotny korpus ekspedycyjny wciąż żyje.$B$BLedwie mogę w to uwierzyć, a jednak oto stoją – świadectwo niezłomności Przymierza.$B$BW tamtej twierdzy przebywa jeden z naszych największych bohaterów: Danath Trollbane! Odszukaj go, $N. Poznał już i przemówił do wszystkich naszych żołnierzy. Z pewnością zechce poznać także ciebie.', 'Porozmawiaj z dowódcą sił Danathem Trollbane\'em w Warowni Honoru.', '', 'Porozmawiaj z dowódcą sił Danathem Trollbane\'em w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9410, 'plPL', 'Duchowy przewodnik', 'Nawet zmysły naszych najlepszych wilków tropiących mogą zawieść, $N. Duchy postrzegają świat inaczej niż my. Istota, którą przywołasz, odnajdzie osobę, której szukasz, bo przyciągnie ją nie zapach, lecz esencja.$B$BIdź teraz, $N, weź ten totem i użyj go w miejscu, w którym $gznalazłeś:znalazłaś; kamienny topór.', 'Użyj totemu wilka w miejscu, w którym $gznalazłeś:znalazłaś; ciało Kruna Łamigrzbieta, i podążaj za wilczym duchem przodków.', '', '', '', '', '', '', 0),
(9417, 'plPL', 'Zagrożenie ze strony arakkoa', 'Arakkoa to bystre stworzenia... bystre jak każdy gnom, jakiego w życiu $gspotkałeś:spotkałaś;. Mają jednak dar do magii i gwałtowny charakter.$B$BOstatnio zaczęły atakować patrole Warowni Honoru i dlatego nas tu przysłano. Widzisz, Mirren i ja to strzelcy sławni na cały świat, a jakże! Ale my się specjalizujemy w ptactwie i zwierzynie... nie w tych... ciskających pioruny ptakoludziach.$B$BTo co powiesz na to, żeby nam pomóc przy tym jednym zadaniu? Norę Haal\'esh znajdziesz na południowym zachodzie.', 'Gremni Długobrody na Półwyspie Piekielnego Ognia chce, żebyś $gzabił:zabiła; 4 wędrowców wiatru Haal\'eshi i 6 szponostrażników Haal\'eshi.', '', 'Wróć do Gremniego Długobrodego na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9418, 'plPL', 'Kula Avruu', '<Gdy przysuwasz kulę bliżej, słyszysz głos, który się do ciebie zwraca.>$B$BWyczuwam, że nie należysz do arakkoa, więc spróbuję wytargować swoją wolność. Nazywam się Aeranas. Niegdyś władałem wschodnimi wiatrami. Mag Haal\'eshi, Avruu, uwięził mnie w tej kuli.$B$BOdnajdź ołtarz, za którego pomocą arakkoa mnie zniewolili. Jest ukryty na południowy wschód od ich nory. Podejdź do niego z kulą i oddaj mi ją, gdy będę wolny. W zamian za wolność nagrodzę cię potężnym skarbem!', 'Zanieś kulę Avruu do Ołtarza Haal\'eshi na południowy wschód od Nory Haal\'esh na Półwyspie Piekielnego Ognia i oddaj ją Aeranasowi, gdy odzyska wolność.', '', '', '', '', '', '', 0),
(9420, 'plPL', 'Najlepszy puch', 'Arakkoa z Nory Haal\'esh, na południe stąd, hodują wspaniały gatunek ptaków zwanych kaliri. Za ich pióra w faktoriach w Azeroth można by dostać kupę forsy. Pomyśl tylko, ile piwa mógłbym za to kupić!$B$BWiesz co, przynieś mi porcję piór kaliri, a dam ci mój własny kapelusz. Co ty na to? Takiego kapelusza nigdzie nie znajdziesz! Umowa stoi?', 'Mirren Długobrody na Półwyspie Piekielnego Ognia chce, żebyś $gprzyniósł:przyniosła; mu 8 piór kaliri od różnych kaliri z Nory Haal\'esh.', '', 'Wróć do Mirrena Długobrodego na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9423, 'plPL', 'Powrót do Obadeia', 'Śmierć Sedaia się potwierdziła, więc zostaje ci przykre zadanie: wrócić do Obadeia z ponurą wieścią.', 'Wróć do anachorety Obadeia w Świątyni Telhamat na Półwyspie Piekielnego Ognia i powiadom go o śmierci Sedaia.', '', '', '', '', '', '', 0),
(9424, 'plPL', 'Zemsta Makuru', 'Sedai był dla Makuru jak brat. Zawdzięczamy mu życie i więcej! Mówią, że Makuru oszalał, ale jeśli Omenai nic nie zrobią z jego śmiercią, to oni są szaleni!$B$BMakuru niewiele ma na tym świecie, ale odda ci jedyną rzecz, jaką posiada, jeśli pomścisz Sedaia.$B$BWidziałem już brązowych orków, siepaczy Mag\'harów, na wzgórzach na północnym wschodzie. Oni nas nienawidzą! Nie zasługują na litość! Idź, pomścij Sedaia! Przynieś mi ich paciorki przodków na dowód!', 'Makuru w Świątyni Telhamat na Półwyspie Piekielnego Ognia chce, żebyś $gprzyniósł:przyniosła; mu 10 paciorków przodków Mag\'harów.', '', 'Wróć do Makuru w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9426, 'plPL', 'Sadzawki Aggonara', 'Wiele się zmieniło od czasów, gdy nazywaliśmy tę krainę Draenorem. Niektóre jej części na zawsze odmieniło skażenie demonów.$B$BJednym z takich miejsc są Sadzawki Aggonara. Niegdyś były tam święte źródła naszego ludu. Krew demona Aggonara zbrukała samą esencję świętych wód. Ta spaczona krew zrodziła plugawe istoty, które trzeba oczyścić, jeśli kiedykolwiek mamy odzyskać sadzawki. Udaj się na wschód stąd i zabij straszydła grozy oraz szlamy, które krążą wokół sadzawek.', 'Amaan Mądry chce, żebyś $gudał:udała; się do Sadzawek Aggonara i $gzabił:zabiła; 6 straszydeł grozy i 6 pęcherzykowych zgnilizn.', '', 'Wróć do Amaana Mądrego w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9427, 'plPL', 'Oczyszczenie wód', 'Muszę cię prosić, byś $gdokończył:dokończyła; to, co zaczęliśmy. Teraz, gdy demoniczny wpływ osłabł, weź tę fiolkę oczyszczenia i wylej ją u samego źródła skażenia – na zwłoki Aggonara.$B$BKości demona znajdziesz na północnym krańcu sadzawek. Uważaj, wyczuwam, że esencja Aggonara nie całkiem opuściła ten świat.', 'Amaan Mądry chce, żebyś $gudał:udała; się do Sadzawek Aggonara i $gużył:użyła; fiolki oczyszczenia przy zwłokach Aggonara. Wróć do niego, gdy esencja Aggonara zostanie wypłukana z wody.', '', 'Wróć do Amaana Mądrego w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', 'Obecność Aggonara oczyszczona', '', '', '', 0),
(9430, 'plPL', 'Relikwie Sha\'naar', 'Jak już ci mówiłem, nie potrzebuję oczu, by widzieć to, czego nie widzą inni. Nie będę osądzał tego, co $gzrobiłeś:zrobiłaś; dla Makuru, ale myślę, że musisz spojrzeć dalej, niż sięga twój wzrok.$B$BUdaj się na południowy zachód do Ruin Sha\'naar i ocal wszelkie relikwie, jakie znajdziesz. Jeśli los zechce, znajdziesz to, czego potrzebujemy.$B$BSens mojej prośby może nie być od razu jasny. Miej jednak wiarę, $N. Jasność przychodzi do cierpliwych.', 'Amaan Mądry w Świątyni Telhamat na Półwyspie Piekielnego Ognia chce, żebyś $gudał:udała; się do Ruin Sha\'naar i $gzdobył:zdobyła; 10 relikwii Sha\'naar.', '', 'Wróć do Amaana Mądrego w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9442, 'plPL', 'Wyniszczająca choroba', 'Dobrze, że $gzaoferowałeś:zaoferowałaś; nam pomoc, $N. Nasi siepacze zachorowali od picia skażonej wody, a mnie brakuje składnika do maści leczniczej. Potrzebuję rzadkiego grzyba zwanego suchołebkiem.$B$BNaszym najważniejszym rozkazem jest utrzymać nasze położenie w tajemnicy i nie ryzykować, że ktoś nas wypatrzy, gdy będziemy go szukać – inaczej poszłabym sama. Jedyne miejsce na Półwyspie Piekielnego Ognia, gdzie rośnie suchołebek, to jaskinia w Wielkiej Szczelinie, na południe stąd.$B$BJeśli zdecydujesz się go poszukać, zachowaj najwyższą ostrożność.', 'Przywoływaczka ziemi Ryga z Posterunku Mag\'harów na Półwyspie Piekielnego Ognia chce, żebyś $gprzyniósł:przyniosła; jej 1 grzyb suchołebek z jaskini w Wielkiej Szczelinie.', '', 'Wróć do przywoływaczki ziemi Rygi w Posterunku Mag\'harów na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9447, 'plPL', 'Podanie maści', 'Z ziół, które $gprzyniosłeś:przyniosłaś;, przygotowałam prostą maść, która powinna przywrócić siły naszym siepaczom. Weź ją i podaj ją wszystkim osłabionym siepaczom, jakich zobaczysz w okolicy. Wróć do mnie, gdy skończysz.', 'Przywoływaczka ziemi Ryga chce, żebyś $gpodał:podała; maść leczniczą 10 osłabionym siepaczom Mag\'harów w pobliżu Posterunku Mag\'harów na Półwyspie Piekielnego Ognia.', '', 'Wróć do przywoływaczki ziemi Rygi w Posterunku Mag\'harów na Półwyspie Piekielnego Ognia.', 'Uleczeni osłabieni siepacze', '', '', '', 0),
(9466, 'plPL', 'Poszukiwany: Czarnoszpon Dziki', 'Z rozkazu kapitana tropicieli niniejszym wyznacza się nagrodę za zabicie okrutnej matrony skalnych oprawców znanej jako Czarnoszpon Dziki.$B$BCzarnoszpona ostatnio widziano w jaskini w Wielkiej Szczelinie. Chętni do zdobycia nagrody mają przedstawić pazury stwora jako dowód czynu.', 'Przynieś pazury Czarnoszpona kapitanowi tropicieli Venn\'renowi w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', 'Wróć do kapitana tropicieli Venn\'rena w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9472, 'plPL', 'Kochanka Areliona', 'Przy tych wszystkich ważnych sprawach Arelion jeszcze znajdował czas na spotkania z kochanką!$B$BTeraz wszystko staje się jasne. Viera Szept Słońca, ta wstrętna dziewka... pokażemy jej, że nie zadziera się z magistrix.$B$BWeź ten zwój i odszukaj Vierę. Znajdź sposób, by zwabić ją z dala od osady, i użyj na niej zwoju.$B$BArelion wspominał, że nie potrafi się oprzeć pewnemu trunkowi wytwarzanemu przez cenariońskich druidów. Może znajdziesz go w Schronieniu Cenariona, tuż za granicą Moczarów Zangarskich, na zachód stąd.', 'Magistrix Carinda z Sokolej Strażnicy chce, żebyś $gzwabił:zwabiła; Vierę Szept Słońca z dala od osady, a potem $gużył:użyła; na niej zwoju odwetu Carindy.', '', 'Wróć do magistrix Carindy w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', 'Użyto zwoju odwetu Carindy', '', '', '', 0),
(9483, 'plPL', 'Drobne przyjemności życia', '', '', '', 'Wróć do Viery Szept Słońca w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9490, 'plPL', 'Matrona skalnych oprawców', 'Skalni oprawcy to podłe, paskudne, agresywne stwory. Ale zwykłe są jak oswojone zwierzęta w porównaniu z ich matroną, Czarnoszponem Dzikim.$B$BPożarła mojego kuzyna i nie był to ładny widok. Przysiągłem, że któregoś dnia Czarnoszpon za to zapłaci. Przynieś mi dowód śmierci tego potwora, a dam ci oszczędności całego życia. Umowa?$B$BDo zabicia Czarnoszpona potrzebujesz przyjaciół. Wielkich, twardych przyjaciół z ostrymi mieczami. Znajdziesz ją w jaskini w Wielkiej Szczelinie. Powodzenia!', 'Zdobądź pazury Czarnoszpona z Czarnoszpona Dzikiego w Wielkiej Szczelinie i zanieś je Ikanowi w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', 'Wróć do Ikana w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9492, 'plPL', 'Odwrócenie losów', 'Nieustające zagrożenie ze strony orków to jedna ze smutnych prawd Rubieży. Był czas, gdy my, Synowie Lothara, wierzyliśmy, że własną krwią okupiliśmy bezpieczeństwo Warowni Honoru, ale pokoju nie było nam dane zaznać.$B$BSynowie nie ugną się przed żadnym orkiem – zielonym, brązowym, a teraz czerwonym. Pokonamy ich albo zginiemy, próbując. Jeśli mamy liczyć na zwycięstwo, musimy ponieść walkę do nich, do Cytadeli Piekielnego Ognia. Przynieś mi broń ich samozwańczego „wodza wojennego” Kargatha Brzytworękiego, a zostaniesz sowicie $gnagrodzony:nagrodzona;.', 'Przynieś Pięść wodza wojennego Kargatha dowódcy sił Danathowi Trollbane\'owi w Warowni Honoru.', '', 'Wróć do dowódcy sił Danatha Trollbane\'a w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9493, 'plPL', 'Duma Spaczonej Hordy', 'Bardzo niewiele wiemy o siłach Spaczonej Hordy w Cytadeli Piekielnego Ognia, a nawet te wiadomości okupiliśmy wieloma istnieniami.$B$BOddziały Spaczonej Hordy pod dowództwem Kargatha Brzytworękiego to brutalna, zaprawiona w boju zgraja wzmocniona plugawą magią. Elita tych sił – legioniści, czempioni i centurioni Strzaskanej Dłoni – budzi lęk wśród zwykłych żołnierzy i pełni rolę korpusu oficerskiego.$B$BWybicie ich to niezbędny pierwszy krok do każdego udanego ataku na przywództwo Spaczonej Hordy.', 'Dowódca polowy Romus w Warowni Honoru chce, żebyś $gzabił:zabiła; 8 legionistów Strzaskanej Dłoni, 4 centurionów Strzaskanej Dłoni i 4 czempionów Strzaskanej Dłoni.', '', 'Wróć do dowódcy polowego Romusa w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9494, 'plPL', 'Węgielki Spaczenia', 'Zatęchli akademicy z Azeroth zbyt długo kulili się w swoich wieżach i to na mnie spadło pokazanie im, czym są prawdziwie przełomowe badania! Boją się igrać z ogniem, a ja właśnie to zamierzam robić – jak tylko dostanę ten ogień w swoje ręce.$B$BW Strzaskanych Salach Cytadeli Piekielnego Ognia Wielki Czarnoksiężnik Nethekurse dokonuje niezrównanych magicznych wyczynów, wspomaganych mocą pary dziwnych koksowników. Za pomocą naczynia, w którym trzyma te węgielki Spaczenia, schwytaj jeden i przynieś mi go, $N.', 'Magini Zabraxis w Warowni Honoru chce, żebyś $gprzyniósł:przyniosła; jej węgielek Spaczenia.', '', 'Wróć do magini Zabraxis w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9495, 'plPL', 'Wola wodza', 'Walka o uwolnienie orków od naszej skażonej krwi nie była łatwa, $N. Wódz Thrall widział zbyt wielu orkowych bohaterów powalonych ręką losu. Teraz wygląda na to, że do ich grona należy także Kargath Brzytworęki.$B$BW Strzaskanych Salach Cytadeli Piekielnego Ognia Kargath obwołał się „wodzem wojennym” Spaczonej Hordy. Z armią oszalałych, żądnych krwi spaczonych orków za plecami nie spocznie, dopóki Thrallmar nie zostanie zniszczony. Wódz Thrall rozkazał nam pokonać Kargatha i jego siły za wszelką cenę.', 'Przynieś Pięść wodza wojennego Kargatha Nazgrelowi w Thrallmarze.', '', 'Wróć do Nazgrela w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9496, 'plPL', 'Duma Spaczonej Hordy', 'Pomijając obelgi nadrządcy Kaleczpięści, $N, z tą Spaczoną Hordą nie ma żartów.$B$BZ tego, co wiemy, oddziały Spaczonej Hordy pod dowództwem Kargatha Brzytworękiego to brutalna, zaprawiona w boju zgraja wzmocniona plugawą magią. Elita tych sił – legioniści, czempioni i centurioni Strzaskanej Dłoni – budzi lęk wśród zwykłych żołnierzy Spaczonej Hordy i pełni rolę korpusu oficerskiego.$B$BWybicie ich to niezbędny pierwszy krok do każdego udanego ataku na przywództwo Spaczonej Hordy.$B', 'Łowca cieni Ty\'jin w Thrallmarze chce, żebyś $gzabił:zabiła; 8 legionistów Strzaskanej Dłoni, 4 centurionów Strzaskanej Dłoni i 4 czempionów Strzaskanej Dłoni.', '', 'Wróć do łowcy cieni Ty\'jina w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9497, 'plPL', '', '', '', '', 'Wróć do nadrządcy Huna Kaleczpięści przy Upadku Grabieżcy na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9498, 'plPL', 'Sokola Strażnica', 'Mój lud niedawno ukończył budowę Sokolej Strażnicy, bazy wypadowej w południowo-zachodniej części Półwyspu Piekielnego Ognia, za Cytadelą Piekielnego Ognia. Będziesz tam $gmile widziany:mile widziana; jako sojusznik, $N.$B$BJeśli szukasz zajęcia, udaj się tam i powiedz kapitanowi tropicieli Venn\'renowi, że to ja cię przysłałem. Dopilnuje, żeby dostały ci się zadania godne kogoś twojego formatu.', 'Zamelduj się u kapitana tropicieli Venn\'rena w Sokolej Strażnicy na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9499, 'plPL', 'Sokola Strażnica', 'Co ty tu jeszcze robisz, $N? Nie $gsłyszałeś:słyszałaś;, że zbudowaliśmy tu, na Półwyspie Piekielnego Ognia, porządny posterunek sin\'dorei?$B$BNa pewno wolisz przebywać wśród innych krwawych elfów, z dala od tego całego... smrodu. Sokolą Strażnicę znajdziesz na południowym zachodzie, za Cytadelą Piekielnego Ognia. Zamelduj się u kapitana tropicieli Venn\'rena, on się tobą zajmie.$B$BDroga jest niebezpieczna i gęsto patrolowana przez zwiadowców Przymierza. Radziłbym podróżować z towarzyszami. Najlepiej z krwawymi elfami.', 'Udaj się do Sokolej Strażnicy w południowo-zachodniej części Półwyspu Piekielnego Ognia i zamelduj się u kapitana tropicieli Venn\'rena.', '', '', '', '', '', '', 0),
(9510, 'plPL', 'Skóry szczeciniastych rozłupokopytów', 'Chcesz się więc na coś przydać? Bardzo brakuje nam skór rozłupokopytów, $N.$B$BNa południowy zachód stąd, w pobliżu miejsca zwanego Sokolą Strażnicą, znajdziesz mnóstwo szczeciniastych rozłupokopytów. Ich skóry doskonale nadają się do garbarstwa. Przynieś mi porcję, a odpowiednio cię wynagrodzę.', 'Zaopatrzeniowiec Braknar z Posterunku Mag\'harów na Półwyspie Piekielnego Ognia chce, żebyś $gprzyniósł:przyniosła; mu 5 skór szczeciniastego rozłupokopyta.', '', 'Wróć do zaopatrzeniowca Braknara na Ziemiach Mag\'harów na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9511, 'plPL', 'Plany bitewne Kargatha', '<TXT>Dokumenty, które $gznalazłeś:znalazłaś; przy ciele Kargatha, szczegółowo opisują coś, co wygląda na plany zmasowanej inwazji na Warownię Honoru.', '', '', '', '', '', '', '', 0),
(9543, 'plPL', 'Pokuta', 'Nasza historia z orkami to nieustanny konflikt, $N. Przez ich żądzę krwi omal nie zostaliśmy wytępieni i od tamtej pory unikamy ich, nawet gdy nie są pod wpływem demonów.$B$BAle ten odwet... Sedai by tego nie chciał. Porozmawiaj z naszym starszym, Amaanem Mądrym. Pomoże rzucić światło na te wydarzenia.', 'Porozmawiaj z Amaanem Mądrym w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9545, 'plPL', 'Relikwia jasnowidza', 'Uparci zamykają umysł i wmawiają sobie jedną prawdę. Mądrzy pozostają otwarci na różne możliwości, które prowadzą do teraźniejszości i z niej wynikają.$B$BZabierz tę relikwię tam, gdzie $gznalazłeś:znalazłaś; Sedaia. Patrz nie oczami, $N, lecz umysłem.', 'Amaan Mądry w Świątyni Telhamat na Półwyspie Piekielnego Ognia chce, żebyś $gwrócił:wróciła; do zwłok Sedaia, na północny wschód od Świątyni Telhamat, i $gużył:użyła; tam relikwii jasnowidza. Po wykonaniu zadania wróć do niego.', '', 'Wróć do Amaana Mądrego w Świątyni Telhamat na Półwyspie Piekielnego Ognia.', 'Otrzymano wizję', '', '', '', 0),
(9558, 'plPL', 'Długobrodzi', 'Mieliśmy kłopot z bandytami arakkoa, którzy napadali na wiele naszych karawan z zaopatrzeniem, więc wynająłem kilku krasnoludów, żeby się nimi zajęli.$B$BTo byli bracia; najstarszy był Gremni Długobrody.$B$BTrochę się o nich martwię. Te szalone krasnoludy zabrały więcej piwa niż jedzenia czy amunicji! Może sprawdzisz, co u nich?$B$BKryjówkę arakkoa, Norę Haal\'esh, znajdziesz daleko na zachód stąd, za Wielką Szczeliną. Rozbili obóz na północny zachód od niej, na południe od Parowu Pyłopiórych.', 'Poszukaj Gremniego Długobrodego na północny zachód od Nory Haal\'esh, daleko na zachód od Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9563, 'plPL', 'Zdobyć zaufanie Mirrena', 'Chcesz zdobyć nasze zaufanie? W dzisiejszych czasach niewielu ufam.$B$BNiedawno arakkoa zabili jednego z naszych. Trochę mnie to rozstroiło.$B$BWiesz co, jeśli udowodnisz swoją lojalność wobec Warowni Honoru i... przyniesiesz mi kufel Gorzkiego ze Strażnicy Otchłani... o tak, to by mi teraz bardzo pasowało... wtedy będę miał dla ciebie propozycję.$B$BBernie w Strażnicy Otchłani trzyma zapas tego piwa.', 'Mirren Długobrody chce, żebyś $gprzyniósł:przyniosła; mu 1 Gorzkie ze Strażnicy Otchłani. Aby ukończyć to zadanie, musisz też osiągnąć reputację „Przyjazny” u Warowni Honoru.', '', 'Wróć do Mirrena Długobrodego na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9572, 'plPL', 'Osłabić Wały', 'Szybko, nie ma wiele czasu. Istnienie Thrallmaru wisi na włosku!$B$BUtknęliśmy między Cytadelą Piekielnego Ognia na zachodzie a Płonącym Legionem na wschodzie. Skoro uwaga Legionu skupia się na Mrocznym Portalu, musimy wykorzystać okazję i uderzyć na spaczone orki z Cytadeli Piekielnego Ognia. Kluczem jest najpierw przebić się przez ich wały!$B$BIdź tam, zabij ich przywódców i przynieś dowód Caza\'rezowi, który stoi po drugiej stronie sali!', 'Zabij Strażnika Warty Gargolmara, Omora Nienaznaczonego i smoka Nazana. Zanieś rękę Gargolmara, kopyto Omora i głowę Nazana Caza\'rezowi w Thrallmarze na Półwyspie Piekielnego Ognia.', '', 'Wróć do Caza\'reza w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9575, 'plPL', 'Osłabić Wały', 'Szybko, $N, nie ma wiele czasu. Istnienie Warowni Honoru wisi na włosku!$B$BUtknęliśmy między Cytadelą Piekielnego Ognia na zachodzie a siłami Płonącego Legionu na wschodzie. Skoro uwaga Legionu skupia się na Mrocznym Portalu, musimy wykorzystać okazję i uderzyć na spaczone orki z Cytadeli Piekielnego Ognia. Kluczem jest najpierw przebić się przez ich wały!$B$BIdź tam, zabij ich przywódców i przynieś dowód Gunny\'emu, który stoi tu naprzeciwko mnie!', 'Zabij Strażnika Warty Gargolmara, Omora Nienaznaczonego i smoka Nazana. Zanieś rękę Gargolmara, kopyto Omora i głowę Nazana Gunny\'emu w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', 'Wróć do Gunny\'ego w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9587, 'plPL', 'Mroczne wieści', 'Przeszukując pobieżnie martwe ciało Vazrudena Herolda, znajdujesz zwinięty list z nienaruszoną jeszcze pieczęcią. W krwistoczerwonym wosku odciśnięto ozdobne „I”. Otwierasz list, a wiadomość, którą czytasz, jest wielce niepokojąca.$B$BDowódca sił Danath Trollbane w Warowni Honoru na pewno zechce to zobaczyć!', 'Zanieś złowieszczy list dowódcy sił Danathowi Trollbane\'owi w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9588, 'plPL', 'Mroczne wieści', 'Przeszukując pobieżnie martwe ciało Vazrudena Herolda, znajdujesz zwinięty list z nienaruszoną jeszcze pieczęcią. W krwistoczerwonym wosku odciśnięto ozdobne „I”. Otwierasz list, a wiadomość, którą czytasz, jest wielce niepokojąca.$B$BNazgrel w Thrallmarze na pewno zechce to zobaczyć!', 'Zanieś złowieszczy list Nazgrelowi w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9589, 'plPL', 'Krew to życie', 'Ten list porządnie tu wszystkich podjudzi. Uznają, że coś da się zrobić z tymi wszystkimi nowymi spaczonymi orkami, gdybyśmy tylko wiedzieli, jak się ich tworzy. Już i tak źle, że musimy walczyć z Płonącym Legionem na wschodzie.$B$BTwój szczęśliwy dzień, słodziutka! Przespacerujesz się do miejsca, które nazywają Krwawym Piecem, w Cytadeli Piekielnego Ognia. Brzmi gorąco!$B$BWejdź tam, zabij trochę spaczonych orków i przynieś próbki ich krwi.$B$BMyślisz, że dasz radę?', 'Zbierz 10 fiolek krwi spaczonego orka i zanieś je Gunny\'emu w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', 'Wróć do Gunny\'ego w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9590, 'plPL', 'Krew to życie', 'Ten list jest niepokojący, i to nie tylko dlatego, że pochodzi od Zdrajcy. Musimy się dowiedzieć, jak tworzą tych nowych spaczonych orków, jeśli mamy ich pokonać! Już i tak źle, że musimy walczyć z Płonącym Legionem na wschodniej flance, a teraz jeszcze nowa armia spaczonych orków na zachodzie!$B$BMusisz przeniknąć do tego Krwawego Pieca w Cytadeli Piekielnego Ognia. Przynieś próbki krwi spaczonych orków, których tam znajdziesz.', 'Zbierz 10 fiolek krwi spaczonego orka i zanieś je centurionowi Caza\'rezowi w Thrallmarze na Półwyspie Piekielnego Ognia.', '', 'Wróć do Caza\'reza w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9607, 'plPL', 'Serce wściekłości', '$N, natychmiast zbierz oddział i zbadaj Krwawy Piec w Cytadeli Piekielnego Ognia! I to znaczy dzisiaj, księżniczko!$B$BMagia, którą dysponujemy, wskazuje, że dzieje się tam coś nienaturalnego. Ale coś potężniejszego w środku blokuje wszelkie dokładniejsze badania tajemną magią. A jakże!$B$BSpodziewaj się silnego oporu – żadna misja, którą tam wysłaliśmy, jeszcze nie wróciła!$B$BZbadaj go dokładnie, a potem zdaj dowódcy sił relację z tego, co zobaczysz.', 'Dokładnie zbadaj Krwawy Piec, a potem zamelduj się u dowódcy sił Danatha Trollbane\'a w Warowni Honoru na Półwyspie Piekielnego Ognia.', 'Dokładnie zbadaj Krwawy Piec', 'Wróć do dowódcy sił Danatha Trollbane\'a w Warowni Honoru na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9608, 'plPL', 'Serce wściekłości', '$N, musisz natychmiast zebrać grupę i zbadać Krwawy Piec w Cytadeli Piekielnego Ognia!$B$BMagiczne wróżby, którymi dysponujemy, wskazują, że dzieje się tam coś nienaturalnego. Ale potężna siła w środku blokuje wszelkie dokładniejsze badania tajemną magią, więc musi to być coś bardzo ważnego.$B$BSpodziewaj się silnego oporu – żadna misja, którą tam wysłaliśmy, nigdy nie wróciła!$B$BZbadaj go dokładnie, a potem zdaj relację z tego, co zobaczysz, Nazgrelowi, doradcy Thralla.', 'Dokładnie zbadaj Krwawy Piec, a potem zamelduj się u Nazgrela w Thrallmarze na Półwyspie Piekielnego Ognia.', 'Dokładnie zbadaj Krwawy Piec', 'Wróć do Nazgrela w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(9724, 'plPL', 'Ostrzeżenie dla Kręgu Cenariona', 'Ekspedycja Cenariońska stała się dużą organizacją o sporej autonomii. Te wydarzenia są jednak na tyle ważne, że musimy ostrzec Krąg Cenariona.$B$BNie martw się, nie każę ci wracać aż do Gaju Luny – nasi emisariusze są tak blisko jak na Półwyspie Piekielnego Ognia.', 'Porozmawiaj z Amythiel Wędrowczynią Mgieł w Posterunku Cenariona na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9732, 'plPL', 'Powrót na bagna', 'Wróć do Ysiel i przekaż jej, że pomoc zostanie jej udzielona, gdy tylko będzie to możliwe.$B$BSprawy w Gaju Luny i w Silithusie zajmują naszych członków, ale zrobimy, co w naszej mocy, by wysłać niezbędne zasoby do Schronienia Cenariona.', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9733, 'plPL', 'Ostrzeżenie dla Kręgu Cenariona', 'Ekspedycja Cenariońska stała się dużą organizacją o sporej autonomii. Te wydarzenia są jednak na tyle ważne, że musimy ostrzec Krąg Cenariona.$B$BNie martw się, nie każę ci wracać aż do Gaju Luny – nasi emisariusze są tak blisko jak na Półwyspie Piekielnego Ognia.', 'Porozmawiaj z Mahuramem Mocne Kopyto w Thrallmarze na Półwyspie Piekielnego Ognia.', '', '', '', '', '', '', 0),
(9734, 'plPL', 'Powrót na bagna', 'Wróć do Ysiel i przekaż jej, że pomoc zostanie jej udzielona, gdy tylko będzie to możliwe.$B$BSprawy w Gaju Luny i w Silithusie zajmują naszych członków, ale zrobimy, co w naszej mocy, by wysłać niezbędne zasoby do Schronienia Cenariona.', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
