INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2891, 'plPL', 'Ku pamięci Naczelnego Dowódcy Przymierza, Anduina Lothara: człowieka, który poświęciłby wszystko w obronie swojego króla, swojego ludu, swojego domu...\n\nNiech nasi wrogowie poznają nasze imiona. Niech nasi sojusznicy uczczą naszą śmierć. Jesteśmy Synami Lothara.\n\n– Generał Turalyon\n', 0),
(2892, 'plPL', 'Tu spoczywa peon mężny. Chciał walczyć, lecz wyszedł z tego tylko bąk potężny.', 0),
(2905, 'plPL', 'Oto dzban z prochami. To prochy mojego rozumu, mojej pasji i mojego zapału. Wszystko to zniszczyło się doszczętnie samo. Niech wszyscy, którzy spoglądają na te spustoszone ziemie Piekielnego Ognia, pamiętają o tym poległym peonie. Przelewał krew dla Przymierza i poświęcał się dla Hordy, tylko po to, by doprowadzili go do całkowitego szaleństwa niegodziwi i bezduszni, którzy pożarli to, co było mu najdroższe. Niech, sycąc się owocami jego trudu, zaznają jego gniewu. Może nie na tym świecie, ale na każdym świecie, który nastanie potem. To moja deklaracja, moja uroczysta przysięga i moja wieczna obietnica. Pomszczę swoje cierpienie.', 0),
(2916, 'plPL', 'Vazrudenie,\n\nOdkąd Mroczny Portal znów się otworzył, Warownia Honoru i Thrallmar otrzymują z Azeroth znaczne posiłki. Widziałem raporty sugerujące, że planują atak na cytadelę, a przecież musimy się też zmagać z Płonącym Legionem. To niedopuszczalne!\n\nNie narażaj operacji w Krwawym Piecu! Produkowane tam spaczone orki są kluczem do naszego sukcesu. Natychmiast wzmocnij obronę na wałach i wystaw więcej straży na obwodzie!\n\nUwierz mi, nie chcesz, żebym złożył ci wizytę.\n\n– Illidan', 0),
(2917, 'plPL', 'Vazrudenie,$B$BOdkąd Mroczny Portal znów się otworzył, Warownia Honoru i Thrallmar otrzymują z Azeroth znaczne posiłki. Widziałem raporty sugerujące, że planują atak na cytadelę, a przecież musimy się też zmagać z Płonącym Legionem. To niedopuszczalne!$B$BNie narażaj operacji w Krwawym Piecu! Produkowane tam spaczone orki są kluczem do naszego sukcesu. Natychmiast wzmocnij obronę na wałach i wystaw więcej straży na obwodzie!$B$BUwierz mi, nie chcesz, żebym złożył ci wizytę.$B$B– Illidan', 0),
(2981, 'plPL', 'Sługo.\n\nTe orki stają się czymś więcej niż drobną uciążliwością. Masz osobiście dopilnować, by nasze siły atakujące obrońców Mrocznego Portalu skierowały całą swoją energię na obrócenie Thrallmaru w perzynę.\n\nUważaj to za rozkaz,\n\nArazzius', 0),
(2982, 'plPL', 'Sługo.\n\nTe orki stają się czymś więcej niż drobną uciążliwością. Masz osobiście dopilnować, by nasze siły atakujące obrońców Mrocznego Portalu skierowały całą swoją energię na obrócenie Thrallmaru w perzynę.\n\nUważaj to za rozkaz,\n\nArazzius', 0),
(2985, 'plPL', 'Generale,$B$BUtrzymujemy linię na Schodach Przeznaczenia, ale Legion posyła fala za falą na nasze szeregi. Muszą mieć gdzieś w pobliżu punkt zborny, którego nasi zwiadowcy jeszcze nie namierzyli. Choć stacjonujące tu siły Przymierza stoją u naszego boku, obawiam się, że przewaga liczebna Legionu przełamie naszą obronę. Przyślij, jaką tylko możesz, pomoc, bo inaczej Portal upadnie – a my zostaniemy na zawsze uwięzieni w tym koszmarnym świecie.$B$BGenerał porucznik Orion', 0),
(2997, 'plPL', 'Pozdrowienia, uczony Antonivichu:\n\nMam nadzieję, że ten list zastanie Cię w Thrallmarze, owocnie prowadzącego badania. Moje wyposażenie tu, w Posterunku Łamigrzbietów, wystarcza do moich eksperymentów, choć czasem chciałbym wrócić do Podmiasta, gdzie miałbym pełen zestaw przyrządów i sług do pomocy...\n\nAch, lamenty trupa.\n\nAle do rzeczy – mam ciekawe wieści: krew, którą $N $gzebrał:zebrała; od spaczonych orków, wykazuje stężenie demonicznego skażenia. Jest ono niemal identyczne ze skażeniem pierwszych spaczonych orków z Azeroth... skażeniem Mannorotha.', 0),
(2999, 'plPL', 'Antonivichu,\n\nNa początek pozwól, że powiem, iż twój najnowszy agent, $n, $gwypełnił:wypełniła; swoje obowiązki ku mojemu wielkiemu zadowoleniu. Zawładnąłem $gjego:jej; ciałem i piszę to teraz $gjego:jej; własną ręką. Jakże mnie to bawi – mam nadzieję, że pewnego dnia będę miał szczęście opętać ciebie, o potężny aptekarzu!\n\nA więc raport, jak mi rozkazałeś: w Cytadeli Piekielnego Ognia przebywa demon potężniejszy od wszystkich, jakie dotąd spotkałem. Wyobrażam sobie, że Mannoroth – lord otchłani, który zasłynął w Trzeciej Wielkiej Wojnie – miał podobną siłę, ale niewielu ją ma. Wyczuwam jednak, że wokół tego demona unosi się aura uwięzienia. Nie zdziwiłbym się, gdyby działał wbrew swojej woli, był może uwięziony albo pozostawał pod wpływem jeszcze większej mocy.\n\nCzas pokaże...', 0),
(3000, 'plPL', 'Czas pokaże, jak to mówią, bo wyczułem też zmianę losu w murach Cytadeli Piekielnego Ognia.\n\nWy, przybysze z Azeroth – tego zielonego, bujnego, okropnego miejsca, gdzie istoty takie jak ja znajdują piekło Światłości i życia – ujrzycie oblicze tego demona. I zrozumiecie, że zło w Cytadeli Piekielnego Ognia to zaledwie wierzchołek – jeśli pozwolisz mi na tę metaforę – ogromnej góry lodowej.\n\nOch, jakież wspaniałe bitwy przed nami! Gdybym tylko mógł tam być i kosztować bólu i strachu, jakie zostaną zasiane!\n\nCóż, zakończę już to prozaiczne rozwodzenie się i zostawię cię, drogi aptekarzu, z tymi słowami do przemyślenia: twoje ciało może i jest martwe, Antonivichu, ale twoja dusza jest wciąż w pełni nienaruszona, a ja zdobędę tę duszę i ucztować będę na niej z wyszukaną rozkoszą w dniu, w którym twoja obrona osłabnie... a ja znajdę drogę do twojego wnętrza!\n\nZaczekam do Czwartego Dnia Sądu, jeśli będzie trzeba, ale... będziesz mój!\n\nDobranoc,\n– D', 0),
(3030, 'plPL', 'Wpływ Mannorotha nie może sięgać aż na Rubież – ta bestia nie żyje od lat – ale obawiam się, że działa tu inny lord otchłani. Lord otchłani o mocy Mannorotha... zdolny zepsuć tutejsze orki.\n\nBędę dalej badał krew Krwawiącego Oczodołu, ale nalegam, abyś podążył tym tropem. A obawiam się, że ten trop może prowadzić w głąb Cytadeli Piekielnego Ognia.\n\nZ naukowym pozdrowieniem,\naptekarz Albreck', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(16700, 3, 5, 'plPL', 'Ruszać się!'),
(16700, 3, 6, 'plPL', 'Do ataku!'),
(16700, 6, 5, 'plPL', 'Ruszać się!'),
(16700, 6, 6, 'plPL', 'Do ataku!'),
(16700, 9, 5, 'plPL', 'Ruszać się!'),
(16700, 9, 6, 'plPL', 'Do ataku!'),
(16976, 0, 1, 'plPL', '%s zaciska pięści w gniewie.'),
(17000, 0, 0, 'plPL', 'Głupcy! Chcecie wypędzić stąd mojego ojca? Czeka was śmierć, śmiertelnicy!'),
(18930, 0, 0, 'plPL', 'Aaarrgh... Straże!'),
(22431, 2, 1, 'plPL', 'Moc Światłości ci rozkazuje! Wracaj do swojej otchłani!'),
(22431, 2, 2, 'plPL', 'Niech Światłość cię oczyści, człowieku! Nie pozwól, by demoniczne zepsucie cię przemogło.'),
(22431, 2, 4, 'plPL', 'Nie... mogę... się... zachwiać!'),
(22432, 1, 2, 'plPL', 'To daremne, draeneiu! Ty i twój mały pomocnik nie wyrwiecie mi tego żałosnego człowieka. Jest mój!'),
(22432, 1, 3, 'plPL', 'Rozszarpię twoją duszę na kąski i będę je powoli piekł nad demonicznym ogniem.'),
(22432, 1, 4, 'plPL', 'Wszystko stracone, anachoreto! Porzuć resztki nadziei.'),
(22432, 1, 5, 'plPL', 'Widzę twoich przodków, anachoreto! Wiją się i wrzeszczą w ciemności... są z nami!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12531, 'plPL', 'Wasza breja gotowa. Chodźcie i bierzcie...', '', 0),
(12532, 'plPL', 'A jak usłyszę, że znowu skarżyliście się Nazgrelowi, patałachy, to następnym razem któregoś z was podam na obiad...', 'A jak usłyszę, że znowu skarżyliście się Nazgrelowi, patałachy, to następnym razem któregoś z was podam na obiad...', 0),
(12547, 'plPL', 'Czy wyczuwam nutę cynamonu? A może to gałka muszkatołowa? Cokolwiek to jest, jedno jest pewne – nikt nie gotuje osła tak jak ty, Ciastek.', 'Czy wyczuwam nutę cynamonu? A może to gałka muszkatołowa? Cokolwiek to jest, jedno jest pewne – nikt nie gotuje osła tak jak ty, Ciastek.', 0),
(12550, 'plPL', 'Gdyby mój żołądek nie groził, że wyrwie się z mojego ciała i porzuci mnie dla odpadków, które dajemy więźniom, może poczułbym się urażony tym... tym jedzeniem.', 'Gdyby mój żołądek nie groził, że wyrwie się z mojego ciała i porzuci mnie dla odpadków, które dajemy więźniom, może poczułbym się urażony tym... tym jedzeniem.', 0),
(12551, 'plPL', 'Widziałem gnomy, które pracowały ciężej od ciebie, peonie! Małe gnomie dziewczynki – z kucykami! RUSZAJ SIĘ, RUSZAJ, RUSZAJ!', '', 0),
(12598, 'plPL', 'Handluję wygodą... Ukój swoje dzikie popędy. Moja karczma jest twoim domem...', '', 0),
(12617, 'plPL', 'No więc byliśmy tam – ja i batalion, na rutynowym zwiadzie wzdłuż kościanej drogi. Wysłaliśmy zwiadowcę przodem, żeby się rozejrzał, gdyby pojawiło się coś groźnego.', '', 0),
(12618, 'plPL', 'No i jasne, zwiadowca przybiegł z powrotem, gadając o jakichś orkach dalej na szlaku. Jeszcze nas nie zauważyli, więc pomyśleliśmy, że pójdziemy się zapoznać.', '', 0),
(12619, 'plPL', 'Jakich orkach, szefie?', '', 0),
(12625, 'plPL', 'Wielkie czerwone bydlaki! Więksi niż jakikolwiek ork, jakiego w życiu widziałem. Mięśnie o, takie, kły o, takie...', '', 0),
(12628, 'plPL', 'Spaczone orki...', '', 0),
(12635, 'plPL', 'Ale jak to, szefie? Myślałem, że klątwa została zdjęta...', '', 0),
(12636, 'plPL', 'Nie wiem, siepaczu. Po prostu – nie – wiem...', '', 0),
(12637, 'plPL', 'Ale to nie jest najgorsze. Zanim zdążyłem nas wycofać, grupka tamtych nas wypatrzyła i zaatakowała.', '', 0),
(12638, 'plPL', 'Straciłem tamtego dnia kilku moich najlepszych żołnierzy...', 'Straciłem tamtego dnia kilku moich najlepszych żołnierzy...', 0),
(12683, 'plPL', 'Wypijemy ich krew i pożremy ich kości!', '', 0),
(12684, 'plPL', 'Służ Spaczonej Hordzie!', '', 0),
(12685, 'plPL', 'Władza dla Spaczonej Hordy!', '', 0),
(12686, 'plPL', 'Łamać im kości!', '', 0),
(12687, 'plPL', 'Znajcie swojego pana, nędzne kundle!', '', 0),
(12691, 'plPL', 'Jakbyście wy, słabeusze, mogli nam zagrozić. Pożremy was.', '', 0),
(12692, 'plPL', 'Zniszczymy was.', '', 0),
(12698, 'plPL', 'Bracia i siostry, byłem w ziemi obiecanej. Kosztowałem wzniosłej energii. Zaznałem błogości – błogości tak pochłaniającej i wszechogarniającej, że zacząłem się zastanawiać, czy nie trafiłem przypadkiem do snów bogów.', '', 0),
(12700, 'plPL', 'Opowiedz nam więcej, Martiku. Co to jest? Jak to jest?', 'Opowiedz nam więcej, Martiku. Co to jest? Jak to jest?', 0),
(12703, 'plPL', 'W raju po prostu wyciągasz rękę i czerpiesz z Otchłani.', '', 0),
(12704, 'plPL', 'Ale jak?', 'Ale jak?', 0),
(12706, 'plPL', 'Z samego powietrza! Macki tajemnej energii rozświetlają obsydianowe niebo, a z rozpadlin w ziemi wznoszą się pióropusze czystej magii. Uklęknij i pij z rozpadliny jak ze strumienia lub studni. Zerwij mackę z niebios, jakby była jabłkiem wiszącym na gałęzi.', 'Z samego powietrza! Macki tajemnej energii rozświetlają obsydianowe niebo, a z rozpadlin w ziemi wznoszą się pióropusze czystej magii. Uklęknij i pij z rozpadliny jak ze strumienia lub studni. Zerwij mackę z niebios, jakby była jabłkiem wiszącym na gałęzi.', 0),
(12707, 'plPL', '%s wstrzymuje oddech z wrażenia.', '%s wstrzymuje oddech z wrażenia.', 0),
(12749, 'plPL', 'Jestem Sid. Miło zobaczyć tu jakieś nowe twarze. Czym mogę służyć?', '', 0),
(12750, 'plPL', 'Chcę obejrzeć twoje towary, Sid.', 'Chcę obejrzeć twoje towary, Sid.', 0),
(12751, 'plPL', 'Chcę, żeby Warownia Honoru stała się moim domem, Sid.', 'Chcę, żeby Warownia Honoru stała się moim domem, Sid.', 0),
(12756, 'plPL', 'Choć dotarliśmy do ziemi obiecanej, $n, wciąż zostało wiele pracy. Nasz lud nie dotrze do Kael\'thasa, jeśli będziemy rozpaczliwie gnać przez Rubież.$B$BTrzeba znaleźć bezpieczne szlaki, zabezpieczyć zasoby, a naszych wrogów omijać albo niszczyć.', '', 0),
(12778, 'plPL', 'Mirren i ja to dwaj najlepsi łowcy po obu stronach Mrocznego Portalu. Zostań trochę, to może się czegoś nauczysz.', '', 0),
(12779, 'plPL', 'Mam nadzieję, że nie $gprzyszedłeś:przyszłaś; po nasze piwo. Nie dzielimy się i koniec!$B$BTo nie nasza wina, że nikt poza nami nie wpadł na tak rozsądny pomysł jak zabranie piwa na Rubież.', '', 0),
(12782, 'plPL', '', 'Oby nie cała Rubież była tak jałowa jak ta okolica. To spora odmiana po zielonych łąkach i lasach Gaju Wszechpieśni.', 0),
(12783, 'plPL', 'Na Rubieży istnieją demoniczne byty znacznie potężniejsze od wszystkiego, co widzieliśmy w starym świecie.$B$BWielka moc przypadnie tym, którzy się przed nią nie cofną, lecz nauczą się ją okiełznać i opanować jej siłę.', '', 0),
(12784, 'plPL', 'Urodziłem się tutaj. To mój świat – wszystko, co znam... Kiedy byłem chłopcem, matka i ojciec raczyli mnie opowieściami o waszym świecie i jego wspaniałościach. Jakże pragnąłem stąd odejść.$B$BNiestety, los bywa okrutny. Moja matka i ojciec dawno odeszli, pochowani na tym właśnie cmentarzu. Zostaję, by strzec ich honoru i honoru mojej rodziny – Synów Lothara.', '', 0),
(12791, 'plPL', 'Rubież wprost ocieka magiczną energią, jest w samym powietrzu. Czujesz ją, $n? Nie potrafię wyobrazić sobie miejsca lepiej pasującego do naszej rasy. Wkrótce sin\'dorei będą mieli nową ziemię, którą nazwą swoją!', '', 0),
(12792, 'plPL', '', 'Mój mąż zaginął kilka dni temu. Wyruszyliśmy razem na tę pielgrzymkę; mieliśmy ją razem ukończyć.$B$BZ tego zmartwienia sięgam po kryształy many częściej, niż powinnam.', 0),
(12797, 'plPL', 'Przyjaźń ze Słońcobieżcami się opłaciła; mogę prowadzić badania na obiektach, które znajdę tylko na Rubieży, a oni dostają... mój czarujący charakter i męską urodę.', '', 0),
(12805, 'plPL', 'Byłem tylko niemowlęciem, gdy mojego ojca wysłano na to pustkowie. Wszystko, co o nim wiem, znam z opowieści innych.$B$BCzy twoje sny się zmieniają, $n? Moje nie. Mam jeden sen: otacza mnie karmazynowy horyzont, a w oddali walczy Legion, niezliczony ponad wszelkie pojęcie. Klęczę nad ciałem mężczyzny, zapewne mojego ojca, i płaczę. Z trudem łapie oddech, całe jego ciało jest zmiażdżone, i coś szepcze. Mimo wszelkich starań nie słyszę, co próbuje mi powiedzieć.', '', 0),
(12836, 'plPL', 'Chronić wodza za wszelką cenę!', 'Chronić wodza za wszelką cenę!', 0),
(12837, 'plPL', 'Śmierć intruzom!', 'Śmierć intruzom!', 0),
(12838, 'plPL', 'Za Łamigrzbieta!', 'Za Łamigrzbieta!', 0),
(12839, 'plPL', 'Pożremy twoje kości!', 'Pożremy twoje kości!', 0),
(13142, 'plPL', 'Jeśli szukasz pracy, $N, weź kilof i do kopania. Ruiny ciągną się tam, jak okiem sięgnąć!', '', 0),
(13143, 'plPL', '', 'Witaj, $n. Ja i moi towarzysze z Synów Lothara tkwimy na tym nędznym świecie od blisko dwudziestu lat. Trzymaliśmy się, jak mogliśmy, ale wciąż mnie zdumiewa, że zagrożenia, z którymi mierzymy się dziś, to tylko cienie naszych dawnych porażek.$B$BMoże pomożesz nam je odkupić?', 0),
(13144, 'plPL', 'Nie przypuszczam, żebyś $gprzyniósł:przyniosła; wieści o kopalniach, co?', '', 0),
(13145, 'plPL', '', 'Rozmiar zepsucia na Rubieży jest naprawdę zdumiewający, $N. Krąg Cenariona chce zrozumieć, jak te stworzenia zdołały przetrwać. Badanie tej zniszczonej, udręczonej krainy i jej mieszkańców może nas jeszcze nauczyć, jak uzdrawiać chore zakątki naszego własnego świata.', 0),
(13146, 'plPL', 'Smutno patrzeć, co się stało z tą krainą. Ekspedycja Cenariońska zrobi, co w jej mocy, by zrozumieć i naprawić wyrządzone szkody.', '', 0),
(13147, 'plPL', 'Wyglądasz na $gzagubionego:zagubioną;, $N. Nie każ mi zapędzić cię do roboty na murach razem z innymi peonami.', '', 0),
(13148, 'plPL', '', 'Witaj, $N. Twoje przybycie do Thrallmaru nie mogło nastąpić w lepszej chwili. Wódz na nas liczy, bo sam nie może tu być.', 0),
(13149, 'plPL', 'Thrallmar cię potrzebuje, $N. Wódz cię potrzebuje. Bądź $ggotów:gotowa; spełnić swój obowiązek.', '', 0),
(13180, 'plPL', 'Moja siła... wraca!', '', 0),
(13181, 'plPL', '$GZnalazłeś:Znalazłaś; lekarstwo! Zmiażdżymy naszych wrogów!', '', 0),
(13182, 'plPL', '$GPrzywróciłeś:Przywróciłaś; mi zdrowie! Mam wobec ciebie dług, $n.', '', 0),
(13184, 'plPL', 'Wszyscy się uspokoić! Robimy, co w naszej mocy, żeby opanować sytuację. Te przeklęte orki nie odpuszczają!', '', 0),
(13186, 'plPL', '%s szlocha.', '%s szlocha.', 0),
(13188, 'plPL', 'Nie możemy już nawet wychodzić z domów! Ataki nie mają końca!', 'Nie możemy już nawet wychodzić z domów! Ataki nie mają końca!', 0),
(13189, 'plPL', 'Niektórymi dniami cmentarz na wzgórzu zapełnia się szybciej, niż nadążamy kopać groby.', 'Niektórymi dniami cmentarz na wzgórzu zapełnia się szybciej, niż nadążamy kopać groby.', 0),
(13190, 'plPL', 'Czy kiedykolwiek będziemy mogli wrócić do domu?', 'Czy kiedykolwiek będziemy mogli wrócić do domu?', 0),
(13191, 'plPL', 'Dziś był pogrzeb mojego syna, Thalvosie... A w zeszłym tygodniu pogrzeb mojej drugiej połowy.', 'Dziś był pogrzeb mojego syna, Thalvosie... A w zeszłym tygodniu pogrzeb mojej drugiej połowy.', 0),
(13192, 'plPL', 'Mówią, że będzie kolejny atak... Nikt nie ma przeżyć...', 'Mówią, że będzie kolejny atak... Nikt nie ma przeżyć...', 0),
(13193, 'plPL', 'Ner\'zhul nigdy się nie podda. Gdzie są nasi bohaterowie?', 'Ner\'zhul nigdy się nie podda. Gdzie są nasi bohaterowie?', 0),
(13194, 'plPL', 'Sam Trollbane nie odeprze połączonej potęgi orkowej Hordy. Już po nas...', 'Sam Trollbane nie odeprze połączonej potęgi orkowej Hordy. Już po nas...', 0),
(13195, 'plPL', 'Chcemy odpowiedzi, poruczniku! Mamy prawo znać prawdę!', 'Chcemy odpowiedzi, poruczniku! Mamy prawo znać prawdę!', 0),
(13255, 'plPL', '', 'Tam! Idą za nami!', 0),
(13289, 'plPL', '', 'Dziękuję, że $gzgodziłeś:zgodziłaś; się pomóc. A teraz uciekajmy stąd, $n!', 0),
(13290, 'plPL', '', 'Pozwól mi chwilę odpocząć. Ta podróż wyczerpuje resztki moich sił.', 0),
(13292, 'plPL', '', 'Nareszcie Sokola Strażnica! A gdzie mój... O nie! Mój plecak, zniknął! Gdzie on się –', 0),
(13303, 'plPL', '', 'Witaj, $N.', 0),
(13304, 'plPL', 'Nie mam czasu na próżne pogawędki, $N. Muszę się zająć pielgrzymami i dopilnować, by byli gotowi na długą drogę.', '', 0),
(13308, 'plPL', '', 'Podążaj zawsze w Światłości, $n.', 0),
(13321, 'plPL', '', 'Chyba zaczynam żałować, że wyruszyłam na tę pielgrzymkę. Spodziewałam się, że droga będzie trudna, a podróże nie są mi obce, ale nie byłam przygotowana na trudy Rubieży.$B$BNa domiar złego ten Taleris chyba chce mnie stąd wypchnąć, zanim w pełni odzyskam siły.', 0),
(13325, 'plPL', 'Obudź się, Gal\'resso.', '', 0),
(13326, 'plPL', '', '%s przeciera zaspane oczy.', 0),
(13327, 'plPL', '', 'Czego chcesz, Talerisie?', 0),
(13328, 'plPL', 'Miałaś dość czasu, by wyleczyć rany, Gal\'resso. Pora, byś wróciła na szlak.', '', 0),
(13329, 'plPL', '', 'Nie ruszę dalej sama, Talerisie, i koniec. Zaczekam tu na następną grupę pielgrzymów i wyruszę razem z nimi.', 0),
(13330, 'plPL', 'Nic takiego nie zrobisz. Po prostu nie mamy miejsca, żeby cię tu trzymać. A teraz bądź łaskawa ruszyć w drogę.', '', 0),
(13331, 'plPL', '', 'Na Słoneczną Studnię, ależ z ciebie tępy łeb! Nie zastraszysz mnie i nie zmusisz do odejścia, Talerisie. A teraz zejdź mi z oczu!', 0),
(13332, 'plPL', 'Dobrze, niech będzie po twojemu. Kiedy będziemy odprawiać innych, to ty odpowiesz za ich cierpienie. Pomyśl o tym.', '', 0),
(13390, 'plPL', 'Wpakowałem się tu w niezłe tarapaty. Wieszczka Regulkut próbowała mnie ostrzec, ale moja lekkomyślność w końcu mnie dopadła.$B$BPrzyszedłem tu zbadać ruiny Zeth\'Gor, ale po drodze natknąłem się na Legion. Teraz jedyne, co mam do pokazania, to paskudna rana na nodze.', '', 0),
(13394, 'plPL', 'Bohaterskie czyny rodu Trollbane\'ów są legendarne. Uwielbiam tego człowieka.$B$BA znaleźć go żywego, na Rubieży...$B$B<Romus patrzy gdzieś obok ciebie.>$B$BKiedy go pierwszy raz zobaczyłem, niemal zemdlałem. Wstrząs był przytłaczający. Klęcząc przed nim, musiałem powstrzymywać łzy.$B$BMożesz być $gpewien:pewna;, że zrobię wszystko, co w mojej mocy, by Synowie Lothara byli bezpieczni.', '', 0),
(13395, 'plPL', 'Romus opowiedział mi o tragediach, które spotkały moje piękne miasto. Nie ma słów, które oddałyby smutek, jaki poczułem, słysząc o losie Lordaeronu – i o losie mojego własnego, ukochanego Stromgardu.$B$BDwadzieścia lat temu nikt nie słyszał o „Płonącym Legionie”... Niech będą przeklęte te diabły!$BBądź $gpewien:pewna;, $n: jeśli kiedykolwiek wrócę do Azeroth, Stromgard znów stanie się siłą, z którą trzeba będzie się liczyć. Przysięgam.', '', 0),
(13447, 'plPL', 'Magia Avruu prysła! Znów mam wolność!', '', 0),
(13448, 'plPL', 'Magia Avruu... wciąż mnie kontroluje. Musisz ze mną walczyć, śmiertelniku. Tylko tak da się złamać zaklęcie!', '', 0),
(13468, 'plPL', 'Podejdź bliżej, przyjacielu. Niech moje oczy cię nie przestraszą.$B$BMoże i straciłem wzrok wiele lat temu, ale nigdy go nie potrzebowałem, by widzieć to, co naprawdę ważne.', '', 0),
(13502, 'plPL', '', 'Niech duchy cię prowadzą.', 0),
(13503, 'plPL', 'Siła dla klanów, $N! Co cię tu sprowadza?', '', 0),
(13512, 'plPL', '', 'Witaj, dobra duszo. Co cię do nas sprowadza?', 0),
(13586, 'plPL', '', 'Jesteś takim dobrym przyjacielem, Migotku. Ty byś mnie nigdy nie zostawił, prawda?', 0),
(13587, 'plPL', '', 'Zostaliśmy tylko ty i ja, Migotku. Tatuś nie wróci do domu.', 0),
(13588, 'plPL', '', 'Znalazłeś coś fajnego do gonienia, Migotku? Założę się, że tak!', 0),
(13589, 'plPL', '', 'Dobra, chodźmy. Znam idealne miejsce!', 0),
(13590, 'plPL', '', 'Nie mogę się doczekać, żeby spróbować tego wina!', 0),
(13591, 'plPL', '', 'Co... się... ze mną dzieje? Zabierzcie ode mnie tego kota!', 0),
(13595, 'plPL', 'Migotek patrzy na Vierę Szept Słońca bardzo wygłodniałym wzrokiem.', '', 0),
(13610, 'plPL', '', 'Viera Szept Słońca umyka, próbując uciec przed Migotkiem.', 0),
(13639, 'plPL', '', 'Czego chcesz?$B$BTo trochę niegrzeczne tak podchodzić do obcych bez powodu, nie sądzisz?', 0),
(13650, 'plPL', 'Niech Światłość będzie z tobą, $N.', '', 0),
(13651, 'plPL', '', 'Wygląda na to, że pomoc wreszcie dotarła! Omenai witają cię w obozie naszych ocalałych, $n.', 0),
(13652, 'plPL', 'Ikan próbuje i próbuje. Myślę, że ci Dreghood są bardzo podobni do Zagubionych, wiesz... zagubieni.', '', 0),
(13653, 'plPL', 'To potrwa, ale ci Złamani poznają drogi Światłości!', '', 0),
(13659, 'plPL', '', 'Nie powstrzymasz mnie przed dotarciem do Sokolej Strażnicy!', 0),
(13663, 'plPL', '', 'Potrzebujesz czegoś, $N? Może mogę ci pomóc.', 0),
(13666, 'plPL', '', 'Dziękuję, $n. Wygląda na to, że świetnie się dogadają.', 0),
(13678, 'plPL', '...potężna mikstura!', '', 0),
(13682, 'plPL', 'Ale gdzie ja znajdę odpowiedni obiekt do testów?', '', 0),
(13683, 'plPL', 'Pij to, ty niebieski bydlaku! Nie posłuchasz, a obiecuję ci powolną, bolesną śmierć!', '', 0),
(13684, 'plPL', 'Hmmm... wygląda na to, że będę potrzebował nowego obiektu do testów.', '', 0),
(13685, 'plPL', 'Żal mi cię, Porzucony. W twojej duszy nie ma światła.', '', 0),
(13991, 'plPL', 'Coś ty zrobił, Makuru?! To nie są nasze obyczaje!', '', 0),
(13992, 'plPL', 'Rozumiem, co czujesz, Makuru. Sedai był przecież moim bratem. Ale nie możemy hańbić jego pamięci, sprzeniewierzając się jego ideałom.', '', 0),
(13997, 'plPL', 'Nie! Nie... Sedai! Orki muszą zapłacić!', '', 0),
(14020, 'plPL', 'Co tam, $gpatałachu:dziewczynko;? Chcesz do mamusi? No to pech. Może wybierz się do klubu oficerskiego w Thrallmarze, żeby ją odzyskać?', '', 0),
(14021, 'plPL', 'Wiesz, gdzie jesteś? To jest Warownia Honoru, kochaniutka! Kochaj ją albo się wynoś!', '', 0),
(14023, 'plPL', 'To nie wycieczka szkolna, robaku! Jesteś teraz na Rubieży! Weź się w garść albo zmykaj z powrotem przez portal.', '', 0),
(14024, 'plPL', 'Nie mam ani czasu, ani ochoty, żeby ci coś tłumaczyć, szumowino! Masz mi do powiedzenia coś ważnego, czy $gprzyszedłeś:przyszłaś; tylko zaprosić mnie na drinka, księżniczko?', '', 0),
(14025, 'plPL', 'Co jest z tobą nie tak, do cholery?!', '', 0),
(14026, 'plPL', 'Widziałem, jak się tu puszysz. Może zrobisz nam wszystkim przysługę i po prostu oddasz sprzęt do zbrojowni?', '', 0),
(14027, 'plPL', 'Kto, na imię Kurdrana, przepuścił cię przez Mroczny Portal?', '', 0),
(14028, 'plPL', 'No, no, no, co my tu mamy? $GCywil:Cywilka;? Czy to nie urocze? U mnie nie licz na żadne specjalne traktowanie!', '', 0),
(14033, 'plPL', 'Ścisz głos, $N!', '', 0),
(14034, 'plPL', 'Jeśli masz coś do powiedzenia, to mów!', '', 0),
(14035, 'plPL', 'Jesteś $gcywilem:cywilką;?', '', 0),
(14036, 'plPL', 'Jestem zajęty, streszczaj się!', '', 0),
(14257, 'plPL', '', 'Witaj, $n. W miarę jak będziesz awansować w szeregach sił Warowni Honoru, udostępnię ci różne towary, które mamy w zapasie.', 0),
(14258, 'plPL', 'Pokaż mi, co mam prawo kupić.', 'Pokaż mi, co mam prawo kupić.', 0),
(14261, 'plPL', 'Witaj w Thrallmarze, $n! W miarę jak będziesz dalej wspierać naszą sprawę, udostępnię ci więcej naszych zapasów.', '', 0),
(14417, 'plPL', '', 'Witaj, $N. Dobrze, że $gpostanowiłeś:postanowiłaś; nas odwiedzić.', 0),
(14781, 'plPL', '', 'Zawsze lubiłam sortować i porządkować rzeczy. Chyba mam to po matce.', 0),
(14976, 'plPL', 'Łowca cieni Denjai przysłał mnie tu z niewielkim oddziałem budowniczych i wojowników, żebyśmy założyli ten posterunek. Ledwie skończyliśmy go budować, a on już domaga się raportów!$B$BJeśli potrzebujesz zapasów, mogę zaoferować parę rzeczy, ale wciąż czekamy na pierwszą dostawę.', '', 0),
(15302, 'plPL', '', 'Poznawanie nowych gatunków roślin jest niezwykle ważne dla naszej ekspedycji. I to nie tylko tych leczniczych czy jadalnych.$B$BRośliny są podstawą istnienia wielu innych form życia. Zrozumienie ich pozwala nam lepiej zrozumieć naturę jako całość.', 0),
(15895, 'plPL', 'Najeźdźcy, balansujecie na skraju zapomnienia! Nadchodzi Płonący Legion, a wraz z nim wasz koniec.', '', 0),
(15899, 'plPL', 'Tak? O co chodzi?', '', 0),
(16015, 'plPL', 'Dziękuję za pomoc w przyrządzeniu maści, $n. Kiedy już uśmierzy ból, sprawdzę, jak daleko zajdę na tej nodze.', '', 0),
(16040, 'plPL', 'Nie mam za dużo czasu na pogaduszki. Chyba że chcesz pomóc z tymi kłopotami w kopalni.', '', 0),
(16042, 'plPL', 'Nie wiem, jak ci dziękować za pomoc z kopalniami. Teraz trzeba tylko przekonać górników, żeby wrócili do roboty.', '', 0),
(16101, 'plPL', 'Same mięśnie, zero mózgu, oto czym są peony! Są świetne, kiedy umiesz je zmotywować, ale trzeba je zapalać kopniakiem, jeśli wiesz, co mam na myśli.', '', 0),
(16109, 'plPL', '', 'Wpadło ci coś w oko, $N?', 0),
(16114, 'plPL', 'Jeśli masz pieniądze, ja mam to, czego potrzebujesz.', '', 0),
(16116, 'plPL', '', 'Rozejrzyj się i daj znać, jeśli coś cię zainteresuje.', 0),
(16121, 'plPL', '', 'Nie spiesz się, obejrzyj broń. Naprawiam też broń i zbroje, jeśli potrzebujesz takich usług.', 0),
(16122, 'plPL', 'Mam dokładnie to, czego potrzebujesz do rzucenia zaklęcia.', '', 0),
(16140, 'plPL', '', 'Od lat Warownia Honoru stawia czoła okropieństwom Półwyspu Piekielnego Ognia. Teraz, gdy portal znów się otworzył i z Azeroth napływa pomoc, może ten krwawy impas wreszcie się skończy.', 0),
(16141, 'plPL', '', 'Szkoda, że wśród naszych licznych wrogów na Półwyspie Piekielnego Ognia są także orki z Cytadeli Piekielnego Ognia.$B$BAle... kto lepiej niż orki rzuci Hordzie wyzwanie i ją zahartuje?', 0),
(16146, 'plPL', 'Mam odznaki do wymiany!', 'Mam odznaki do wymiany!', 0),
(16286, 'plPL', 'Oto moc Światłości! Łaska i chwała Przymierzu!', '', 0),
(16346, 'plPL', 'Szeregiem, zmiażdżyć tych głupców!', '', 0),
(16347, 'plPL', 'Formować szyk! Szybko się z nimi rozprawmy!', '', 0),
(16349, 'plPL', 'Przygotować się! To nie potrwa długo...', '', 0),
(16350, 'plPL', 'Żadnej litości! Formować szyk!', '', 0),
(16352, 'plPL', 'Lok-Narash! Pozycje obronne!', '', 0),
(16353, 'plPL', 'Utrzymać linię! Nie mogą się przedrzeć!', '', 0),
(16355, 'plPL', 'Musimy powstrzymać ich natarcie! Zająć pozycje!', '', 0),
(16356, 'plPL', 'Wojownik padł!', '', 0),
(16357, 'plPL', 'Zmiana, szybko!', '', 0),
(16358, 'plPL', 'Następny wojownik, już!', '', 0),
(16359, 'plPL', 'Zbiórka! Mok-thora ka!', '', 0),
(16360, 'plPL', 'Gdzie moje wsparcie?', '', 0),
(16361, 'plPL', 'Następny wojownik, wystąp!', '', 0),
(16362, 'plPL', 'Do walki! Agrama-ka!', '', 0),
(16363, 'plPL', 'Pobudka, atakują nas!', '', 0),
(16364, 'plPL', 'Śpij w wolnym czasie!', '', 0),
(16365, 'plPL', 'Wstawaj!', '', 0),
(16366, 'plPL', 'Na nogi!', '', 0),
(16367, 'plPL', 'Nie czas na drzemkę! Do walki!', '', 0),
(16390, 'plPL', 'Nie będę was okłamywał, żołnierze. Dostajemy tam łupnia! Który z was jest na tyle orkiem, żeby coś z tym zrobić?', '', 0),
(16391, 'plPL', 'Wódz wyznaczył nagrodę za głowę Arazziusa! Od tej chwili ten nic niewart demoniczny śmieć jest wrogiem numer jeden.', '', 0),
(16392, 'plPL', 'No, mamy problemy. Myślę, że to jasne jak słońce. Pytanie brzmi, co z tym zrobimy?', '', 0),
(16393, 'plPL', 'Ilu jeszcze z was, siepacze, mam odesłać mamusi i tatusiowi w worku na zwłoki, zanim wyrośnie wam mózg i zrozumiecie, że pakowanie się na łeb na szyję w oddział egzekucyjny Legionu to samobójstwo? I nie kiwajcie mi tu tymi zakutymi łbami, jakbyście wiedzieli, o czym mówię!', '', 0),
(16394, 'plPL', 'Przyzwyczajajcie się, panienki. O ile mnie to dotyczy, zostajemy tu do końca naszego nędznego życia. Witajcie na Półwyspie Piekielnego Ognia, w waszym nowym domu.', '', 0),
(16395, 'plPL', 'NADCHODZĄ! Nie przepuścić ich! Skupić ogień! JUŻ, JUŻ, JUŻ!', '', 0),
(16421, 'plPL', 'Szybciej, hołoto! Pan nie będzie zadowolony, jeśli nie znajdziemy kryształu Ata\'mal, którego szuka.', '', 0),
(16424, 'plPL', 'Kop szybciej, nędzniku! Nie zmuszaj mnie, żebym pokazał ci, czym jest prawdziwy ból!', '', 0),
(16425, 'plPL', 'Nie przestawaj! Obiecuję ci tysiąc śmierci, jeśli choćby pomyślisz o odłożeniu kilofa!', '', 0),
(16427, 'plPL', '', 'Musimy odkryć, co kryje się za tajemnicą ogromnego kryształu, który spadł z niebios na Grań Upadłego Nieba.', 0),
(16428, 'plPL', 'Czasem najprostsze podejście do problemu jest najlepsze.', '', 0),
(16429, 'plPL', 'Panie, zawiodłem...', '', 0),
(16430, 'plPL', 'Jeśli kiedykolwiek pojmie cię Legion, powiedz im: „Xar il romath da tidesbi”. Zabiją cię natychmiast za obrazę ich boga, oszczędzając ci nieznośnych tortur albo czegoś gorszego...', '', 0),
(16431, 'plPL', 'Lecę na misję bombową dla dowódcy straży przedniej To\'archa. Potrzebuję niszczycielskiej wiwerny!', 'Lecę na misję bombową dla dowódcy straży przedniej To\'archa. Potrzebuję niszczycielskiej wiwerny!', 0),
(16432, 'plPL', 'Bezczelne szczeniaki, tylko opóźniacie nieuniknione. Tam, gdzie padnie jeden, powstanie dziesięciu. Taka jest wola Kazzaka...', '', 0),
(16438, 'plPL', 'Śmiesz przeszkadzać w przedsięwzięciach Pana? Zapłacisz za to, głupi śmiertelniku!', '', 0),
(16439, 'plPL', 'Zabijcie tych intruzów, plugawi Dreghood! Obiecuję wam niekończący się ból, jeśli mnie nie posłuchacie!', '', 0),
(16440, 'plPL', 'Naprzód, nędzne robaki! Pokażcie tym głupcom, że z naszym Panem nie ma żartów!', '', 0),
(16441, 'plPL', 'Nawet nie myślcie o ucieczce, nędzni Złamani! Obiecuję wam los gorszy od śmierci, jeśli nie zabijecie tych intruzów!', '', 0),
(16451, 'plPL', '', 'Półwysep Piekielnego Ognia to rozbita kraina – bezlitosna i nieprzejednana dla swoich mieszkańców. Zanim wyruszysz, koniecznie napraw ekwipunek i zaopatrz się w zapasy.', 0),
(16453, 'plPL', 'Ilu jeszcze żołnierzy musi zginąć, zanim zaczniemy tam uważać?', '', 0),
(16454, 'plPL', 'Myślicie, że demony będą grać uczciwie? Te bestie są bardziej dzikie niż orki i bardziej przebiegłe niż nieumarli. Nie próbujcie walczyć z Legionem według zwykłych reguł wojny.', '', 0),
(16455, 'plPL', 'Z przykrością muszę was wszystkich poinformować, że dziś odesłaliśmy do domu kolejnych dziesięciu żołnierzy – w workach na zwłoki.', '', 0),
(16456, 'plPL', 'Ta wojna – i nie myślcie, że to cokolwiek innego niż wojna – sama się nie wygra. Jeśli nie będziemy walczyć, drapać, szarpać i kopać o każdy skrawek ziemi na tym roztrzaskanym świecie, wszystko będzie stracone.', 'Ta wojna – i nie myślcie, że to cokolwiek innego niż wojna – sama się nie wygra. Jeśli nie będziemy walczyć, drapać, szarpać i kopać o każdy skrawek ziemi na tym roztrzaskanym świecie, wszystko będzie stracone.', 0),
(16457, 'plPL', 'Mów ciszej i miej oczy szeroko otwarte, $n. Jesteśmy tu otoczeni przez wrogów.', '', 0),
(16462, 'plPL', 'Okropne... po prostu okropne!$B$BLecieliśmy sobie spokojnie ze Strefy 52 w Burzy Otchłani, a oni nas zestrzelili! Wiedziałem, że nie powinniśmy lecieć tym skrótem do Puszczy Terokkar!', '', 0),
(16469, 'plPL', 'Wybacz mi... nie mam wyboru.', '', 0),
(16470, 'plPL', 'Zrobię, o co prosisz, demonie. Przynajmniej na razie.', '', 0),
(16471, 'plPL', 'Skróć moje cierpienia!', '', 0),
(16472, 'plPL', 'Zaharujcie tych nędznych Złamanych na śmierć, Illidarowie! Jeśli w tym zapomnianym miejscu jest cokolwiek cennego, znajdziemy to!', '', 0),
(16473, 'plPL', 'Punkt Ekspedycji to najbliższe Frontowi Legionu miejsce, w którym Przymierze się z nim styka. Na północ stąd nie ma nic poza demonami, demonami i jeszcze raz demonami. Nie chodź sam.', '', 0),
(16474, 'plPL', 'Pilnujcie dobrze tej złamanej hołoty! Za wielu już nam uciekło!', '', 0),
(16475, 'plPL', 'Znajdziemy to, czego szuka Pan! Porażka nie wchodzi w grę!', '', 0),
(16476, 'plPL', 'Nie dawajcie tym nędznikom ani chwili odpoczynku! Jeśli jest tu kryształ Ata\'mal, znajdziemy go!', '', 0),
(16481, 'plPL', 'Illidarskie demony trzymają mnie tutaj ze względu na moją wiedzę o starożytnych draenejskich kryształach i relikwiach.$B$BZniewolili wielu z mojego ludu i każą nam szukać potężnego kryształu... którego najpewniej tu nawet nie ma.', '', 0),
(16485, 'plPL', 'Czemu nie uciekniesz?', 'Czemu nie uciekniesz?', 0),
(16487, 'plPL', 'Po co? Jeśli nie złapią mnie i znów nie zniewolą demony Illidana, zrobią to nagowie z Moczarów Zangarskich.$B$BPrzyłączenie się do Illidana i jego sojuszników dla większości plemion Złamanych okazało się niczym innym jak niewolą. Dla mojego ludu nie ma nadziei.', '', 0),
(16504, 'plPL', 'Przysięgam, nigdy więcej nie polecę na skróty! Skąd miałem wiedzieć, że niebo nad Półwyspem Piekielnego Ognia jest aż tak niebezpieczne?', '', 0),
(16573, 'plPL', 'NADCIĄGA DESZCZ PIEKIELNIKÓW! KRYĆ SIĘ!', '', 0),
(16574, 'plPL', 'PIEKIELNIKI! OPRÓŻNIĆ DZIEDZINIEC!', '', 0),
(16575, 'plPL', 'ATAKUJĄ NAS! DO SCHRONÓW!', '', 0),
(16576, 'plPL', 'Rozebrać to, żołnierze! Wysyłamy to cudo do Wichrogrodu!', '', 0),
(16577, 'plPL', 'Przetopimy ten złom i zrobimy broń ze sztabek! Zobaczymy, jak Legionowi zasmakuje grabieżca Spaczenia podany po przymierzowemu!', '', 0),
(16578, 'plPL', 'Dobra robota, żołnierze! Nie pozwolimy, żeby te plugawe zwierzęta z Hordy nas przyćmiły!', '', 0),
(16579, 'plPL', 'Niech tylko rzucą w nas kolejną z tych przerośniętych puszek! Pokażemy im, z czego jest zrobione Przymierze!', '', 0),
(16597, 'plPL', 'Idź dalej, chyba że masz sprawę do floty.', '', 0),
(16616, 'plPL', 'Łowcy, do mnie! Pokażmy tym demonom, co znaczy walczyć i umierać w Azeroth!', '', 0),
(16617, 'plPL', 'Duchy nam śpiewają! Śpiewają pieśń bitwy!', '', 0),
(16618, 'plPL', 'Celnie uderzajcie, bracia i siostry! Dziś naszą zwierzyną są demony!', '', 0),
(16620, 'plPL', 'Po raz kolejny pokażemy temu Płonącemu Legionowi, że nasz świat nie jest do wzięcia!', '', 0),
(16621, 'plPL', 'Te bestie przegrają! Za Azeroth!', '', 0),
(16622, 'plPL', 'Jeśli sądzone nam dziś zginąć, nie pójdzie im z nami łatwo! Zapamiętajcie moje słowa, te demony padną jak kłosy pszenicy!', '', 0),
(16624, 'plPL', 'Choć wasze ścięgna słabną, a krew spływa z ran i skaleczeń na tę przesiąkniętą ziemię, walczycie za duchy waszego świata. Żadna zła siła nie zdoła nam się przeciwstawić!', '', 0),
(16625, 'plPL', 'Żołnierze Azeroth, walczycie teraz z plugawą Płonącą Krucjatą. A nadzieje i modlitwy wszystkich miłujących Światłość ludzi maszerują razem z wami. U boku naszych dzielnych sojuszników i towarzyszy broni utrzymacie pozycje i złamiecie tę demoniczną szarżę. Powstrzymacie niszczycielską tyranię, która szaleje na tak wielu światach.', '', 0),
(16627, 'plPL', 'Demony nie powinny mieć wątpliwości, że jesteśmy ich nemezis i choć pragną naszej zagłady, to my doprowadzimy je do ruiny. Kazzak i jego siły zostaną osłabione i pokonane przez tę koalicję. A żeby tego dokonać, musimy rzucić przeciwko nim nasze ciała i serca, bo one dążą do niczego innego jak unicestwienia tego świata.', '', 0),
(16633, 'plPL', 'Z każdą chwilą widzę, jak mieszkańcy Azeroth na nowo udowadniają, po co tu przybyliśmy. Z uroczystą dumą walczę u waszego boku, a jeśli dziś zginę, to zginę wśród przyjaciół.', '', 0),
(16646, 'plPL', '%s zaczyna rosnąć w siłę.', '', 0),
(16744, 'plPL', '%s rozpaczliwie się broni.', '', 0),
(16746, 'plPL', '%s wyczuwa w pobliżu świeże zwłoki.', '', 0),
(16767, 'plPL', 'Światłości, daj mi siłę.', 'Światłości, daj mi siłę.', 0),
(16769, 'plPL', 'Światłości, prowadź poległych od fałszu do prawdy, od ciemności do Światłości i od śmierci do nieśmiertelności.', 'Światłości, prowadź poległych od fałszu do prawdy, od ciemności do Światłości i od śmierci do nieśmiertelności.', 0),
(16770, 'plPL', 'Światłość niech będzie z tobą teraz i na wieki.', 'Światłość niech będzie z tobą teraz i na wieki.', 0),
(16771, 'plPL', '%s zaczyna szaleńczo rechotać, a oczy rozbłyskują mu czerwienią!', '', 0),
(16772, 'plPL', 'Kapłan klęka w cichej modlitwie.', 'Kapłan klęka w cichej modlitwie.', 0),
(16858, 'plPL', 'Głupcze! Jesteś dzieckiem bawiącym się w świecie, którego nie pojmujesz. Milcz!', '', 0),
(16859, 'plPL', 'Twoja broń nic dla mnie nie znaczy! Poddaj się!', '', 0),
(16860, 'plPL', 'Ufasz swoim umiejętnościom? Zastanów się dobrze, bo odpowiedź może cię zaskoczyć.', '', 0),
(16933, 'plPL', 'Walczcie dalej, dobrzy ludzie Azeroth. I nie traćcie ducha! Wasi pobratymcy spieszą do tego piekielnego portalu i wkrótce rzucą się na te demony tak dzielnie jak wy. Niech Światłość was strzeże!', 'Walczcie dalej, dobrzy ludzie Azeroth. I nie traćcie ducha! Wasi pobratymcy spieszą do tego piekielnego portalu i wkrótce rzucą się na te demony tak dzielnie jak wy. Niech Światłość was strzeże!', 0),
(16935, 'plPL', 'Moi pobratymcy, moi towarzysze broni! Muszę odszukać siły Hordy i skierować je tutaj! Nie traćcie ducha, dzielni łowcy! Nie dajcie się pokonać tym bestiom z portalu!', '', 0),
(16981, 'plPL', 'Ja mówię, żeby wystrzelić. Przetnij linę.', 'Ja mówię, żeby wystrzelić. Przetnij linę.', 0),
(16982, 'plPL', 'Phi! Tchórz.', 'Phi! Tchórz.', 0),
(16983, 'plPL', 'Ty przetnij linę. Ty masz nóż.', 'Ty przetnij linę. Ty masz nóż.', 0),
(16986, 'plPL', 'Wiesz co, chyba stąd dosięgniemy Warowni Honoru.', 'Wiesz co, chyba stąd dosięgniemy Warowni Honoru.', 0),
(16987, 'plPL', 'Ha! Powiemy mu, że Hagash się o to potknął i przypadkiem wystrzelił!', 'Ha! Powiemy mu, że Hagash się o to potknął i przypadkiem wystrzelił!', 0),
(16988, 'plPL', 'Gdyby generał Krakork się dowiedział, zjadłby nas żywcem. Nie rób tego.', 'Gdyby generał Krakork się dowiedział, zjadłby nas żywcem. Nie rób tego.', 0),
(16990, 'plPL', 'Jestem ślepy, wy głupie pomioty maciory, a nie głuchy. Nawet o tym nie myślcie.', '', 0),
(17083, 'plPL', '', 'Czy to ty jesteś $gkorespondentem:korespondentką; „Kuriera Gadżetonu”? Jeśli pójdziesz za mną, pokażę ci moją eksperymentalną aparaturę...$B$B<Mówisz magini, że nie jesteś osobą z gazety, na którą czeka.>$B$BAch, nie? Cóż, jeśli potrzebujesz odczynników, znajdź, czego ci trzeba, i nie marudź. Czekam na kogoś.', 0),
(17105, 'plPL', '%s pochłania energię ognia z ataku.', '', 0),
(17106, 'plPL', '%s pochłania energię mrozu z ataku.', '', 0),
(17107, 'plPL', '%s pochłania energię natury z ataku.', '', 0),
(17108, 'plPL', '%s pochłania energię cienia z ataku.', '', 0),
(17109, 'plPL', '%s pochłania tajemną energię z ataku.', '', 0),
(17110, 'plPL', '%s pochłania świętą energię z ataku.', '', 0),
(17338, 'plPL', '%s staje się niestabilny i zaczyna się rozpadać!', '%s staje się niestabilny i zaczyna się rozpadać!', 0),
(17407, 'plPL', 'Dzięki niebiosom, że tu $gdotarłeś:dotarłaś;, już prawie była pora obiadu!', '', 0),
(17409, 'plPL', 'Już myślałem, że po mnie.', '', 0),
(17410, 'plPL', 'Nie wiem, co gorsze – dać się zjeść spaczonym orkom czy pracować dla tego poganiacza niewolników Razelcraza! No, ale i tak dzięki!', '', 0),
(17418, 'plPL', 'Pożycz mi wiwernę. Lecę do Posterunku Łamigrzbietów!', 'Pożycz mi wiwernę. Lecę do Posterunku Łamigrzbietów!', 0),
(17457, 'plPL', 'Urtrak cię zabić!', '', 0),
(17461, 'plPL', 'Formować szeregi, niech intruzi zapłacą!', '', 0),
(17462, 'plPL', 'Powstrzymać ich za wszelką cenę!', '', 0),
(17467, 'plPL', 'Opowiedz mi o Synach Lothara.', 'Opowiedz mi o Synach Lothara.', 0),
(17470, 'plPL', 'Wiele lat temu wraz z moimi ludźmi podążyliśmy za czarodziejem Khadgarem i paladynem Turalyonem do tego świata. Naszym jedynym celem było unicestwienie orków i ich plugawych pobratymców. A jednak w ostatnich godzinach naszej wojny coś poszło strasznie źle.$B$BOstatecznie ten mroczny świat został rozdarty na strzępy – a moi drodzy przyjaciele przepadli w pustce.', '', 0),
(17471, 'plPL', '<dalej>', '<dalej>', 0),
(17472, 'plPL', 'My, Synowie Lothara, zostaliśmy tu od tamtej pory – walcząc... ginąc... modląc się, by nadszedł dzień taki jak dziś – dzień, w którym Portal się otworzy, a nasi bracia przybędą, by zabrać nas do domu.$B$BChoć ogromnie się cieszymy, obowiązek wciąż wzywa. Wiele jest do zrobienia, zanim będziemy mogli opuścić ten świat i odpocząć.', '', 0),
(17478, 'plPL', 'Wyślij mnie do Warowni Honoru!', 'Wyślij mnie do Warowni Honoru!', 0),
(17483, 'plPL', 'Ach, nowy czempion, który wesprze naszą sprawę? Co ty na to, $n?', '', 0),
(17484, 'plPL', '$n, Synowie Lothara walczą tutaj, na Półwyspie Piekielnego Ognia, od dwóch dekad. Ze wszystkich stron osaczają nas tutejsze orki i piekielne demony Płonącej Krucjaty i choć nasze serca wciąż biją zawzięcie, lata wojny przerzedziły nasze szeregi.$B$BTy i napływ nowego pokolenia bohaterów z Azeroth to doprawdy mile widziany widok!', '', 0),
(17489, 'plPL', 'Opowiedz mi o orkach z Piekielnego Ognia.', 'Opowiedz mi o orkach z Piekielnego Ognia.', 0),
(17490, 'plPL', 'Orki. Mam wrażenie, że walczę z nimi przez całe życie.$B$BDwadzieścia lat temu rozbiliśmy Hordę i zburzyliśmy mury ich Cytadeli Piekielnego Ognia. Zepchnęliśmy tych plugawych zielonoskórych na sam skraj przepaści! Potem, poza kilkoma potyczkami, rozbite orki nigdy więcej nam nie zagroziły.$B$BAż do teraz.', '', 0),
(17514, 'plPL', 'Witaj w Warowni Honoru, $n. Dobrze cię tu mieć.', '', 0),
(17521, 'plPL', 'Mniej więcej dwadzieścia lat temu Przymierze wysłało pierwszą Ekspedycję do tego świata w nadziei, że raz na zawsze wytępi orki. To był... straszliwy konflikt. Wiele dzielnych dusz zginęło, by zapewnić Azeroth bezpieczeństwo.$B$BA jednak niektóre dusze pozostały... uwięzione w wiecznej walce.', '', 0),
(17523, 'plPL', 'Mężczyźni i kobiety z Warowni Honoru przelali tyle krwi i stracili młodość w tej potwornej krainie... a mimo to wciąż nie tracą ducha!$B$BTeraz ty i twoi towarzysze z Azeroth możecie pomóc nam odwrócić losy wojny. Dajecie nam nadzieję, że pewnego dnia wrócimy do naszych ojczyzn.', '', 0),
(17525, 'plPL', 'Opowiedz mi o swojej ojczyźnie.', 'Opowiedz mi o swojej ojczyźnie.', 0),
(17593, 'plPL', '%s przywołuje swoje worgi.', '', 0),
(17653, 'plPL', 'Co za zuchwałość! Co za arogancja! Wierzyć, że zdołasz mnie pokonać na moim własnym progu!', '', 0),
(17755, 'plPL', 'Daruj mi życie! Powiem ci o sekrecie Areliona.', '', 0),
(17756, 'plPL', 'Czego chcesz? Nie przepadam za pogawędkami.', '', 0),
(17757, 'plPL', 'Magistrix Carinda przysłała mnie, żebym $gzapytał:zapytała; o sekret Areliona. Z kim on się spotykał?', 'Magistrix Carinda przysłała mnie, żebym $gzapytał:zapytała; o sekret Areliona. Z kim on się spotykał?', 0),
(17758, 'plPL', 'Jeśli myślisz, że tak łatwo zdradzę przyjaciela, to się mylisz! Stań do walki, łotrze!', '', 0),
(17798, 'plPL', 'Jeszcze cię uruchomię, ty kupo złomu.', '', 0),
(17802, 'plPL', 'Co?! Myślisz, że nie dam rady? Jeszcze ci pokażę... jak tylko zdobędę części.', '', 0),
(17803, 'plPL', 'No jasne, bardzo śmieszne, co?', '', 0),
(17804, 'plPL', 'Ruszyło się! Przysięgam, widziałem, jak się ruszyło!', '', 0),
(17805, 'plPL', 'Au! Tak nie powinno być.', '', 0),
(17809, 'plPL', 'Streszczaj się, $N – toczymy tu wojnę, jeśli nie $gzauważyłeś:zauważyłaś;.', '', 0),
(17899, 'plPL', 'Throm\'ka, $N. Musisz być tu $gnowy:nowa;. Wyglądasz świeżo, $gnietknięty:nietknięta; przez okropieństwa tej krainy.$B$B<Sierżant Łamaczaszka spluwa w pył.>$B$BTo się zmieni.', '', 0),
(17905, 'plPL', 'Moi bracia w Wichrogrodzie mówili mi, żebym nie wstępował do wojska... Cieszę się, że ich nie posłuchałem!', '', 0),
(17906, 'plPL', 'Cypel Strzaskania to świetne miejsce dla krasnoluda z klanu Dzikiego Młota. Nigdzie indziej nie spędza się tyle czasu w powietrzu!', 'Cypel Strzaskania to świetne miejsce dla krasnoluda z klanu Dzikiego Młota. Nigdzie indziej nie spędza się tyle czasu w powietrzu!', 0),
(17935, 'plPL', 'Wyślij mnie na Cypel Strzaskania!', 'Wyślij mnie na Cypel Strzaskania!', 0),
(17936, 'plPL', 'Wyślij mnie do Punktu Honoru!', 'Wyślij mnie do Punktu Honoru!', 0),
(17937, 'plPL', 'Wyślij mnie na Cypel Strzaskania!', 'Wyślij mnie na Cypel Strzaskania!', 0),
(17964, 'plPL', 'Porozmawiaj z dowódcą skrzydła Brackiem, $n. Wyposaży cię w jedną z naszych opancerzonych niszczycielskich wiwern. I powodzenia!', '', 0),
(17965, 'plPL', 'Witaj, $N! Zgłaszasz się na misję lotniczą?', '', 0),
(18080, 'plPL', '%s wstrzymuje oddech z wrażenia.', '', 0),
(18168, 'plPL', 'Na brodę Muradina, $N. Ta kraina jest na skraju zagłady. Nie potrafię sobie wyobrazić, że ktokolwiek przetrwał tu od końca drugiej wojny.', 'Na brodę Muradina, $N. Ta kraina jest na skraju zagłady. Nie potrafię sobie wyobrazić, że ktokolwiek przetrwał tu od końca drugiej wojny.', 0),
(18198, 'plPL', 'Lecę na misję bombową dla dowódcy straży przedniej Kingstona. Potrzebuję niszczycielskiego gryfa!', 'Lecę na misję bombową dla dowódcy straży przedniej Kingstona. Potrzebuję niszczycielskiego gryfa!', 0),
(18199, 'plPL', 'Jeśli masz mdłości, porozmawiaj z Pestle\'em. Może ma coś na chorobę lokomocyjną.', '', 0),
(18200, 'plPL', 'Wyślij mnie na Półkę Bezdni!', 'Wyślij mnie na Półkę Bezdni!', 0),
(18272, 'plPL', 'Witaj na Cyplu Strzaskania, $n! Mam nadzieję, że przeżyjesz to doświadczenie!', '', 0),
(18289, 'plPL', '', 'Mam pomysł. Zasadźmy ten odłamek w ziemi i zobaczmy, co się stanie.', 0),
(18291, 'plPL', '', 'Zło bijące z kryształowego odłamka zwabiło jednego z kolosów. Szybko go powal!', 0),
(18293, 'plPL', '', 'Tutaj, na wzgórzu, $n.', 0),
(18349, 'plPL', 'To ten złamany robak dał ci ten kostur, prawda? Powiedział ci też, że to on sprzedał swoje plemię? Nieważne, za to zapłacicie – ty i on!', '', 0),
(18352, 'plPL', 'Duch wody nas opuścił. Nasze plemię jest zgubione.', '', 0),
(18353, 'plPL', 'Idź wolny, starszy. Sprowadź duchy z powrotem do swojego plemienia.', 'Idź wolny, starszy. Sprowadź duchy z powrotem do swojego plemienia.', 0),
(18354, 'plPL', 'Wiatry już nie przemawiają do naszego plemienia, $n. Mój lud jest zgubiony bez starszych, którzy sprowadzą do niego duchy.', '', 0),
(18355, 'plPL', 'Łańcuchy, które mnie krępują, nie pozwalają mi sprowadzić ducha ognia do mojego ludu, $n. Dusze bez ognia to dusze, które nie potrafią zbuntować się przeciwko swoim panom.', '', 0),
(18356, 'plPL', 'Jestem wolny! Poproszę ducha ognia, by do nas powrócił, by mój lud miał odwagę walczyć ze swoimi panami! Dziękuję ci.', '', 0),
(18357, 'plPL', 'Jestem wolny! Duch wody wraca do mojego ludu. Przyniesie nam mądrość, której potrzebujemy, by przetrwać w tej surowej krainie. Mam wobec ciebie dług, $n.', '', 0),
(18358, 'plPL', '$GUwolniłeś:Uwolniłaś; mnie! Wiatry znów przemawiają do mojego ludu i użyczają nam swojej siły. Dziękuję ci, $gnieznajomy:nieznajoma;.', '', 0),
(18373, 'plPL', '', 'Twoja pomoc była bezcenna, przyjacielu.$B$BZapewniam cię, że Ekspedycja Cenariońska zrobi wszystko, co w jej mocy, by przeciwdziałać wszelkim skażonym kryształom, które Illidan jeszcze zrzuci z niebios.', 0),
(18771, 'plPL', 'Jak ci się podoba wojna, $n? Pamiętaj tylko, po co tu jesteśmy... wtedy walka i umieranie są o wiele łatwiejsze.', '', 0),
(18772, 'plPL', 'Służba w Punkcie Ekspedycji jest ciężka, ale ten punkt ma kluczowe znaczenie dla obrony Warowni Honoru. Informacje zebrane tutaj oraz starcia naszych żołnierzy z Legionem i orkami z Zeth\'Gor są bezcenne dla kampanii Przymierza na Półwyspie Piekielnego Ognia.', '', 0),
(18774, 'plPL', 'Rozlega się głęboki, mrożący krew w żyłach głos – to %s...', '', 0),
(18775, 'plPL', 'Jak śmiesz igrać z moimi zabawkami, $n!', '', 0),
(18776, 'plPL', 'Orki z mojej cytadeli wypiją twoją krew i cię pożrą!', '', 0),
(18823, 'plPL', 'Synowie Lothara toczą wojnę bez końca. Zdumiewa mnie, że nasz sprzęt jest wciąż w tak dobrym stanie!', '', 0),
(18867, 'plPL', '', 'Królewskie Zakłady Chemiczne z Podmiasta chętnie pomogą tu, na Rubieży, naszym orkowym sojusznikom. To okazja, by zacieśnić nasze więzi i znaleźć nowe okazy i związki do badań.$B$BZwiązki... takie jak trucizny.', 0),
(18916, 'plPL', 'Mówią mi, że pył i upał Półwyspu Piekielnego Ognia są bardzo dokuczliwe... Nie wiem, ale zaufam moim szanownym, wciąż żywym sojusznikom.', '', 0),
(18926, 'plPL', 'Tym orkom musi naprawdę zależeć na zdobyciu swojego kawałka Rubieży! Gdybym ci powiedział, ile płacą mi za moją lojalność, $gzabiłbyś:zabiłabyś; mnie z zazdrości!', '', 0),
(19022, 'plPL', '', 'Dziękuję, $n. A teraz przeprowadźmy test...', 0),
(19023, 'plPL', '', 'Ach, rozumiem...', 0),
(19024, 'plPL', '', 'Tak, to niefortunne.', 0),
(19025, 'plPL', '', '$n, potwierdziłam, że ta krew pochodzi od orków z klanu Szpikożerców, skażonych demoniczną mocą. Obawiam się jednak, że mój obecny sprzęt nie pozwala zgłębić tej tajemnicy...', 0),
(19065, 'plPL', 'Wybacz, rozpoczynam badania...', '', 0),
(19066, 'plPL', 'Interesujące...', '', 0),
(19067, 'plPL', 'Ale co to jest?', '', 0),
(19068, 'plPL', 'O rety!', '', 0),
(19069, 'plPL', 'Gdyby moja krew nie skrzepła dawno temu, gotowałaby się teraz z wściekłości...', '', 0),
(19592, 'plPL', 'Pracować ciężej!', '', 0),
(19593, 'plPL', 'Kopać skała! Kruszyć kamień! Szybciej! Szybciej!', '', 0),
(19855, 'plPL', '', 'Posterunek Łamigrzbietów to świetne miejsce do stacjonowania! Te wynaturzenia z Krwawiącego Oczodołu są tak blisko, że czuć ich plugawą krew! Gdzie lepiej szukać zemsty na klanie, który porzucił swoich braci i zawarł pakt z demonami?', 0),
(19933, 'plPL', 'W tym miejscu są tajemnice, które my, orki, rozpaczliwie pragniemy odkryć. Tajemnice naszej przeszłości, tajemnice naszej przyszłości i tajemnice, które pozwalają zajrzeć w głąb nas samych.$B$BMam nadzieję przeniknąć te tajemnice... czy pójdziesz tą drogą ze mną?', '', 0),
(20076, 'plPL', 'Dobrze pamiętam gorycz porażki pod koniec Trzeciej Wojny. Zbyt długo czekałem na zemstę. Teraz cień Legionu pada na ten świat. To tylko kwestia czasu, aż całe wasze nieudane stworzenie... zostanie unicestwione.', '', 0),
(20077, 'plPL', 'Legion podbije wszystko!', '', 0),
(20078, 'plPL', 'Wszyscy śmiertelnicy zginą!', '', 0),
(20079, 'plPL', 'Wszelkie życie musi zostać wytępione!', '', 0),
(20080, 'plPL', 'Zedrę ci mięso z kości!', '', 0),
(20081, 'plPL', 'Kirel narak!', '', 0),
(20082, 'plPL', 'Nędzny robaku!', '', 0),
(20083, 'plPL', 'Wszechświat zostanie stworzony na nowo.', '', 0),
(20084, 'plPL', 'Legion... nigdy... nie upadnie.', '', 0),
(20141, 'plPL', '%s cię dostrzega!', '', 0),
(20260, 'plPL', 'Niech Światłość cię prowadzi, $n.', '', 0),
(20263, 'plPL', 'Z uroczystą dumą pełnię swoją posługę w Warowni Honoru.', '', 0),
(20287, 'plPL', 'Znów $gprzeszedłem:przeszłam; szkolenie alchemika. Chcę się specjalizować w miksturach.', 'Znów $gprzeszedłem:przeszłam; szkolenie alchemika. Chcę się specjalizować w miksturach.', 0),
(20290, 'plPL', 'Jestem Zarevhi z Konsorcjum. Moje umiejętności transmutacji znane są w tysiącu światów.', '', 0),
(20292, 'plPL', 'Znów $gprzeszedłem:przeszłam; szkolenie alchemika. Chcę się specjalizować w transmutacji.', 'Znów $gprzeszedłem:przeszłam; szkolenie alchemika. Chcę się specjalizować w transmutacji.', 0),
(20301, 'plPL', 'Zemsta nie będzie twoja, $n!', '', 0),
(20302, 'plPL', '$GSłyszałem:Słyszałam;, że twój pies Fei Fei zabrał różaniec Klatu...', '$GSłyszałem:Słyszałam;, że twój pies Fei Fei zabrał różaniec Klatu...', 0),
(20303, 'plPL', '', 'O nie! Mój Fei Fei nigdy nie wziąłby cudzych rzeczy! To dobry pies... po prostu czasem potrzebuje uwagi. Daj mu smakołyk, to zobaczysz!', 0),
(20306, 'plPL', '<wróć>', '<wróć>', 0),
(20312, 'plPL', '%s kopie w ziemi...', '', 0),
(20313, 'plPL', '%s zakopuje swój smakołyk!', '', 0),
(20315, 'plPL', '%s obwąchuje okolicę, niezadowolony z tej kryjówki.', '', 0),
(20316, 'plPL', '%s szuka kryjówki...', '', 0),
(20396, 'plPL', 'Jestem $ggotów:gotowa;, anachoreto. Zacznijmy egzorcyzm.', 'Jestem $ggotów:gotowa;, anachoreto. Zacznijmy egzorcyzm.', 0),
(20397, 'plPL', 'Och, dziękuję! Otchłań ciemności we mnie zniknęła! Znów widzę... i widzę twarz $gmojego wybawcy:mojej wybawczyni;!', '', 0),
(20398, 'plPL', 'Precz stąd! Zostaw nas w spokoju, bo w następnej kolejności wstąpimy w ciebie i pokażemy ci prawdziwą rozpacz!', '', 0),
(20400, 'plPL', 'Już czas. Rozpoczyna się obrzęd egzorcyzmu...', '', 0),
(20401, 'plPL', 'Przygotuj się. Nie pozwól przerwać rytuału, bo możemy stracić pacjenta...', '', 0),
(20402, 'plPL', 'Precz. Ten głupiec jest mój.', '', 0),
(20403, 'plPL', 'Niech Światłość cię oczyści, człowieku! Nie pozwól, by demoniczne zepsucie cię przemogło.', '', 0),
(20404, 'plPL', 'Precz, plugawe istoty ciemności! Nie macie tu żadnej mocy!', '', 0),
(20405, 'plPL', 'Moc Światłości ci rozkazuje! Wracaj do swojej otchłani!', '', 0),
(20406, 'plPL', 'W imię Światłości! To Światłość ci rozkazuje! To Światłość strąciła cię w otchłań ciemności!', '', 0),
(20407, 'plPL', 'Nie... mogę... się zachwiać!', '', 0),
(20408, 'plPL', 'Światłość jest moim przewodnikiem... jest moim pokarmem!', '', 0),
(20409, 'plPL', 'Nie zwiedziesz mnie, demonie! Twoja siła słabnie, a moja wiara rośnie!', '', 0),
(20410, 'plPL', 'Zostawisz... tego... człowieka... w... spokoju!', '', 0),
(20411, 'plPL', 'Dajcie nam czas... Niech człowiek umrze... Jestem nikim... Jestem nikim... Bójcie się anachorety... Bójcie się anachorety... Barada... Barada.', '', 0),
(20412, 'plPL', 'Nie! Jeszcze nie! Ta dusza jest nasza!', '', 0),
(20414, 'plPL', 'Ach! Przestań z tymi zaklęciami, anachoreto! Przestań, albo pokażę ci taki ból, jakiego twój żałosny lud nigdy sobie nie wyobrażał!', '', 0),
(20415, 'plPL', 'Widzę twoich przodków, anachoreto! Wiją się i wrzeszczą w ciemności... są z nami!', '', 0),
(20416, 'plPL', 'To daremne, draeneiu! Ty i twój mały pomocnik nie wyrwiecie mi tego żałosnego człowieka. Jest mój!', '', 0),
(20417, 'plPL', 'Rozszarpię twoją duszę na kąski i będę je powoli piekł nad demonicznym ogniem!', '', 0),
(20418, 'plPL', 'Wszystko stracone, anachoreto! Porzuć resztki nadziei.', '', 0),
(20419, 'plPL', 'Precz! Odpędzam cię... niszczycielu wiary! Sprawco bólu! Nie wracaj, bo spotka cię ten sam los co dzisiaj!', '', 0),
(20424, 'plPL', 'Nie martw się. Cypel Strzaskania jest solidny jak mało co! Ale na wszelki wypadek bądź $ggotów:gotowa; wskoczyć na gryfa, gdyby baza zaczęła się rozpadać...', '', 0),
(20646, 'plPL', 'Obawiam się, że pułkownika Julesa może ocalić tylko niebezpieczny rytuał... egzorcyzm.', '', 0),
(20754, 'plPL', 'Uczta zepsucia dobiegła końca! Magtheridon padł przed bitewnym kunsztem $n i $gjego:jej; sojuszników! Oto potęga Przymierza! Lord otchłani, jeden z dowódców Legionu, został zniszczony!', '', 0),
(20755, 'plPL', 'Słuchajcie mnie, bracia i siostry broni! Czas naszych wrogów dobiega końca! Musimy uderzyć na pozostałe spaczone orki! Wytępcie je jak szkodniki, którymi są! Nieście ze sobą łaskę Synów Lothara!', '', 0),
(21417, 'plPL', '', '<Angela znów grucha do łowcy spaczenia, zanim zwróci na ciebie uwagę.>$B$BJir\'see zawsze był mniejszy od wszystkich innych łowców spaczenia, ale nigdy mu to nie przeszkadzało. A Rubież to wszystko zmieni, prawda, Jir\'see?$B$BMamusi mały aniołek wyrośnie na wielkiego, groźnego łowcę spaczenia, tak, tak!', 0),
(21874, 'plPL', 'Chcę zapomnieć mistrzostwo mikstur.', 'Chcę zapomnieć mistrzostwo mikstur.', 0),
(21876, 'plPL', 'Chcę zapomnieć mistrzostwo transmutacji.', 'Chcę zapomnieć mistrzostwo transmutacji.', 0),
(23118, 'plPL', '', '%s szlocha.', 0),
(24022, 'plPL', '', 'To brama, przez którą armie Kaela wycofały się do Słonecznej Studni. Zostało tu kilku jego pieszczoszków; Legion nagrodził ich w bardzo... nietypowy sposób.', 0),
(24084, 'plPL', 'Nasze wysiłki się opłaciły. Zdobyliśmy Sanktuarium Słonecznego Zasięgu, $n. Idź tam i zobacz, czy możesz komuś pomóc.', '', 0),
(24085, 'plPL', 'Uzbrojenie osłon w sanktuarium pomoże nam szybciej je zabezpieczyć. Nie chcemy, żeby jacyś Nędzni weszli nam w drogę, gdy przypuścimy zmasowany atak na Legion i Kaela.$B$BNasz cel jest osiągnięty w $3244w procentach.', '', 0),
(25568, 'plPL', 'Chcę coś od ciebie kupić.', 'Chcę coś od ciebie kupić.', 0),
(33066, 'plPL', 'Ołtarz otaczają porywiste wiatry. Jest na nim puste miejsce, gdzie kiedyś mogła spoczywać niewielka kula.', '', 0),
(35332, 'plPL', '$GPrzyszedłeś:Przyszłaś; nauczyć się jeździć?', '', 0),
(35826, 'plPL', 'Do ataku!', 'Do ataku!', 0),
(36921, 'plPL', 'Panie, zawiodłem...', '', 0),
(66614, 'plPL', 'Co masz na sprzedaż?', 'Co masz na sprzedaż?', 0);
